    { const char * tb_v531 = "    tb_outw(0x3CE, 0x0004); tb_outw(0x3CE, 0x1005); tb_outw(0x3CE, 0x0E06);\n"; *(const char * *)tb_grow(v_lines) = tb_v531; }
    { const char * tb_v532 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v532; }
