    { const char * tb_v868 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v868; }
    { const char * tb_v869 = "// авария ядра: красным на экран и в порт, потом стоп\n"; *(const char * *)tb_grow(v_lines) = tb_v869; }
    { const char * tb_v870 = "__attribute__((noreturn)) static void tb_panic(const char *what, uint64_t a, uint64_t b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v870; }
    { const char * tb_v871 = "    __asm__ volatile(\"cli\");\n"; *(const char * *)tb_grow(v_lines) = tb_v871; }
