    { const char * tb_v877 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v877; }
    { const char * tb_v878 = "// --- таблица сегментов x86-64: код 64 бита, данные, задача процессора (TSS, 16 байт) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v878; }
    { const char * tb_v879 = "// у каждого ядра процессора свой TSS (две записи по 8 байт): номер сегмента 0x18 + 16 × ядро\n"; *(const char * *)tb_grow(v_lines) = tb_v879; }
    { const char * tb_v880 = "TB_API uint64_t tb_gdt[3 + 2 * TB_NCPU] __attribute__((used)) = {0, 0x00AF9A000000FFFFULL, 0x00CF92000000FFFFULL};\n"; *(const char * *)tb_grow(v_lines) = tb_v880; }
    { const char * tb_v881 = "// TSS: ist[0] — отдельный стек для двойной ошибки (стек упёрся в сторожа — обработчику есть куда писать)\n"; *(const char * *)tb_grow(v_lines) = tb_v881; }
    { const char * tb_v882 = "typedef struct __attribute__((packed)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v882; }
