    { const char * tb_v887 = "TB_API struct __attribute__((packed)) { uint16_t lim; uint64_t base; } tb_gdtr, tb_idtr;\n"; *(const char * *)tb_grow(v_lines) = tb_v887; }
    { const char * tb_v888 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v888; }
    { const char * tb_v889 = "// 49 входов: 0..31 ошибки процессора, 32..47 железо (таймер, клавиатура ...), 48 — «уступить ход».\n"; *(const char * *)tb_grow(v_lines) = tb_v889; }
    { const char * tb_v890 = "// Кадр на стеке (снизу вверх): 512 байт дробей и SSE (fxsave), 15 регистров, номер, код ошибки,\n"; *(const char * *)tb_grow(v_lines) = tb_v890; }
    { const char * tb_v891 = "// и то, что положил процессор: rip, cs, rflags, rsp, ss. Задачи переключаются сменой кадра —\n"; *(const char * *)tb_grow(v_lines) = tb_v891; }
    { const char * tb_v892 = "// у каждой задачи свои регистры и свои дроби лежат в её кадре.\n"; *(const char * *)tb_grow(v_lines) = tb_v892; }
    { const char * tb_v893 = "extern char tb_isr_base[];\n"; *(const char * *)tb_grow(v_lines) = tb_v893; }
    { const char * tb_v894 = "__asm__(\".text\\n.balign 16\\n.global tb_isr_base\\ntb_isr_base:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v894; }
    { const char * tb_v895 = "        \".set tb_v, 0\\n.rept 50\\n.balign 16\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v895; }
    { const char * tb_v896 = "        \".if (tb_v == 8) || (tb_v == 10) || (tb_v == 11) || (tb_v == 12) || (tb_v == 13) || (tb_v == 14) || (tb_v == 17) || (tb_v == 21)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v896; }
    { const char * tb_v897 = "        \".else\\npushq $0\\n.endif\\npushq $tb_v\\njmp tb_isr_common\\n.set tb_v, tb_v + 1\\n.endr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v897; }
    { const char * tb_v898 = "        \"tb_isr_common:\\ncld\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v898; }
    { const char * tb_v899 = "        \"pushq %rax\\npushq %rcx\\npushq %rdx\\npushq %rbx\\npushq %rbp\\npushq %rsi\\npushq %rdi\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v899; }
    { const char * tb_v900 = "        \"pushq %r8\\npushq %r9\\npushq %r10\\npushq %r11\\npushq %r12\\npushq %r13\\npushq %r14\\npushq %r15\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v900; }
    { const char * tb_v901 = "        \"subq $512, %rsp\\nfxsave (%rsp)\\nmovq %rsp, %rdi\\ncall tb_isr\\nmovq %rax, %rsp\\ncall tb_switch_done\\nfxrstor (%rsp)\\naddq $512, %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v901; }
    { const char * tb_v902 = "        \"popq %r15\\npopq %r14\\npopq %r13\\npopq %r12\\npopq %r11\\npopq %r10\\npopq %r9\\npopq %r8\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v902; }
    { const char * tb_v903 = "        \"popq %rdi\\npopq %rsi\\npopq %rbp\\npopq %rbx\\npopq %rdx\\npopq %rcx\\npopq %rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v903; }
    { const char * tb_v904 = "        \"addq $16, %rsp\\niretq\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v904; }
    { const char * tb_v905 = "#define TB_F_VEC 79\n"; *(const char * *)tb_grow(v_lines) = tb_v905; }
    { const char * tb_v906 = "#define TB_F_ERR 80\n"; *(const char * *)tb_grow(v_lines) = tb_v906; }
    { const char * tb_v907 = "#define TB_F_RIP 81\n"; *(const char * *)tb_grow(v_lines) = tb_v907; }
