    { const char * tb_v909 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v909; }
    { const char * tb_v910 = "// --- задачи: у каждой свой стек и свои «переменные потока» (temp, кэш длины) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v910; }
    { const char * tb_v911 = "#define TB_TLS_MAX 512\n"; *(const char * *)tb_grow(v_lines) = tb_v911; }
    { const char * tb_v912 = "#define TB_NTASK 32\n"; *(const char * *)tb_grow(v_lines) = tb_v912; }
    { const char * tb_v913 = "#define TB_TSTACK 65536\n"; *(const char * *)tb_grow(v_lines) = tb_v913; }
    { const char * tb_v914 = "typedef struct { pthread_t th; volatile int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v914; }
    { const char * tb_v915 = "typedef struct {\n"; *(const char * *)tb_grow(v_lines) = tb_v915; }
    { const char * tb_v916 = "    uint64_t *frame; int used; volatile int done;\n"; *(const char * *)tb_grow(v_lines) = tb_v916; }
    { const char * tb_v917 = "    void *(*run)(void *); void *arg; tb_task *t;\n"; *(const char * *)tb_grow(v_lines) = tb_v917; }
    { const char * tb_v918 = "    int on;                               // на каком ядре процессора идёт сейчас (-1 — ни на каком)\n"; *(const char * *)tb_grow(v_lines) = tb_v918; }
    { const char * tb_v919 = "    int no;                               // номер клетки: по порядку запуска (1, 2, 3 ...)\n"; *(const char * *)tb_grow(v_lines) = tb_v919; }
    { const char * tb_v920 = "    uint64_t gen; long long mem;          // поколение слота (для хозяина кусков) и байты клетки\n"; *(const char * *)tb_grow(v_lines) = tb_v920; }
    { const char * tb_v921 = "    int *locks[8]; int nlocks;            // замки, которые клетка держит сейчас\n"; *(const char * *)tb_grow(v_lines) = tb_v921; }
    { const char * tb_v922 = "    unsigned char tls[TB_TLS_MAX + 16] __attribute__((aligned(16)));   // блок переменных потока + адрес самого себя\n"; *(const char * *)tb_grow(v_lines) = tb_v922; }
    { const char * tb_v923 = "} tb_kslot;\n"; *(const char * *)tb_grow(v_lines) = tb_v923; }
    { const char * tb_v924 = "TB_API tb_kslot tb_slots[TB_NTASK];          // 0 — main\n"; *(const char * *)tb_grow(v_lines) = tb_v924; }
    { const char * tb_v925 = "TB_API unsigned char tb_tstacks[TB_NTASK][TB_TSTACK] __attribute__((aligned(4096)));\n"; *(const char * *)tb_grow(v_lines) = tb_v925; }
    { const char * tb_v926 = "TB_API int tb_nlive = 1, tb_cell_count = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v926; }
    { const char * tb_v927 = "// своё у каждой задачи (переменные потока): номер её слота; у функций прерывания tb_in_irq = 1\n"; *(const char * *)tb_grow(v_lines) = tb_v927; }
    { const char * tb_v928 = "TB_API _Thread_local int tb_cur = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v928; }
    { const char * tb_v929 = "TB_API _Thread_local int tb_in_irq = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v929; }
    { const char * tb_v930 = "TB_API unsigned char tb_fpu_init[512] __attribute__((aligned(16)));\n"; *(const char * *)tb_grow(v_lines) = tb_v930; }
    { const char * tb_v931 = "TB_API volatile uint64_t tb_ms = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v931; }
    { const char * tb_v932 = "TB_API void (*tb_irq_fn[16])(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v932; }
    { const char * tb_v933 = "TB_API uint16_t tb_pic_mask = 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v933; }
    { const char * tb_v934 = "TB_API uint64_t tb_tls_size(void) { return (uint64_t)(tb_tls_end - tb_tls_start); }\n"; *(const char * *)tb_grow(v_lines) = tb_v934; }
    { const char * tb_v935 = "// блок переменных потока: начальные значения (образ от компоновщика), в конце — адрес конца\n"; *(const char * *)tb_grow(v_lines) = tb_v935; }
    { const char * tb_v936 = "// (так устроено у x86-64: FS указывает на конец блока, а там лежит он сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v936; }
    { const char * tb_v937 = "TB_API unsigned char *tb_tls_fresh(unsigned char *b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v937; }
    { const char * tb_v938 = "    uint64_t n = tb_tls_size();\n"; *(const char * *)tb_grow(v_lines) = tb_v938; }
    { const char * tb_v939 = "    memcpy(b, tb_tls_start, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v939; }
    { const char * tb_v940 = "    unsigned char *tp = b + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v940; }
    { const char * tb_v941 = "    *(uint64_t *)tp = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v941; }
    { const char * tb_v942 = "    return tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v942; }
    { const char * tb_v943 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v943; }
    { const char * tb_v944 = "TB_API void tb_set_fs(unsigned char *tp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v944; }
    { const char * tb_v945 = "    uint64_t v = (uint64_t)(uintptr_t)tp;\n"; *(const char * *)tb_grow(v_lines) = tb_v945; }
    { const char * tb_v946 = "    __asm__ volatile(\"wrmsr\" : : \"c\"(0xC0000100u), \"a\"((uint32_t)v), \"d\"((uint32_t)(v >> 32)) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v946; }
    { const char * tb_v947 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v947; }
    { const char * tb_v948 = "TB_API unsigned char *tb_tls_tp(unsigned char *b) { return b + tb_tls_size(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v948; }
    { const char * tb_v949 = "TB_INL void *tb_tls_self(void) { void *p; __asm__ volatile(\"movq %%fs:0, %0\" : \"=r\"(p)); return p; }\n"; *(const char * *)tb_grow(v_lines) = tb_v949; }
    { const char * tb_v950 = "// хозяин куска: номер слота и поколение; кусок клетки, которой уже нет, никому не засчитывается\n"; *(const char * *)tb_grow(v_lines) = tb_v950; }
    { const char * tb_v951 = "TB_API uint64_t tb_cell_charge(size_t bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v951; }
    { const char * tb_v952 = "    if (tb_in_irq) return 0xFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v952; }
    { const char * tb_v953 = "    tb_kslot *s = &tb_slots[tb_cur];\n"; *(const char * *)tb_grow(v_lines) = tb_v953; }
    { const char * tb_v954 = "    if (tb_cur != 0 && s->mem + (long long)bytes > TB_CELL_QUOTA) return (uint64_t)-1;\n"; *(const char * *)tb_grow(v_lines) = tb_v954; }
    { const char * tb_v955 = "    s->mem += (long long)bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v955; }
    { const char * tb_v956 = "    return (uint64_t)tb_cur | (s->gen << 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v956; }
    { const char * tb_v957 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v957; }
    { const char * tb_v958 = "// хватит ли клетке квоты, если её кусок вырастет на месте (иначе растём через malloc — он и уронит)\n"; *(const char * *)tb_grow(v_lines) = tb_v958; }
    { const char * tb_v959 = "TB_API int tb_cell_fits(uint64_t tag, long long more) {\n"; *(const char * *)tb_grow(v_lines) = tb_v959; }
    { const char * tb_v960 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v960; }
    { const char * tb_v961 = "    if (i == 0 || i >= TB_NTASK || tb_slots[i].gen != (tag >> 8)) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v961; }
    { const char * tb_v962 = "    return tb_slots[i].mem + more <= TB_CELL_QUOTA;\n"; *(const char * *)tb_grow(v_lines) = tb_v962; }
    { const char * tb_v963 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v963; }
    { const char * tb_v964 = "TB_API void tb_cell_refund(uint64_t tag, long long bytes) {\n"; *(const char * *)tb_grow(v_lines) = tb_v964; }
    { const char * tb_v965 = "    uint64_t i = tag & 0xFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v965; }
    { const char * tb_v966 = "    if (i >= TB_NTASK || tb_slots[i].gen != (tag >> 8) || !tb_slots[i].used) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v966; }
    { const char * tb_v967 = "    tb_slots[i].mem -= bytes;\n"; *(const char * *)tb_grow(v_lines) = tb_v967; }
    { const char * tb_v968 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v968; }
    { const char * tb_v969 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v969; }
    { const char * tb_v970 = "TB_API void tb_pic_apply(void) { tb_outb(0x21, (unsigned char)tb_pic_mask); tb_outb(0xA1, (unsigned char)(tb_pic_mask >> 8)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v970; }
    { const char * tb_v971 = "TB_API void tb_irq_set(int v, void (*fn)(void)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v971; }
    { const char * tb_v972 = "    tb_irq_fn[v - 32] = fn;\n"; *(const char * *)tb_grow(v_lines) = tb_v972; }
    { const char * tb_v973 = "    tb_pic_mask &= (uint16_t)~(1u << (v - 32));\n"; *(const char * *)tb_grow(v_lines) = tb_v973; }
    { const char * tb_v974 = "    if (v >= 40) tb_pic_mask &= (uint16_t)~(1u << 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v974; }
    { const char * tb_v975 = "    tb_pic_apply();\n"; *(const char * *)tb_grow(v_lines) = tb_v975; }
    { const char * tb_v976 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v976; }
    { const char * tb_v977 = "TB_API void tb_irq_on(void) { __asm__ volatile(\"sti\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v977; }
    { const char * tb_v978 = "TB_API void tb_irq_off(void) { __asm__ volatile(\"cli\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v978; }
    { const char * tb_v979 = "TB_API void tb_yield(void) { if (!tb_in_irq) __asm__ volatile(\"int $48\" ::: \"memory\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v979; }
    { const char * tb_v980 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v980; }
    { const char * tb_v981 = "// переключение задач: запомнить кадр и «переменные потока» текущей, отдать кадр следующей\n"; *(const char * *)tb_grow(v_lines) = tb_v981; }
    { const char * tb_v982 = "TB_API uint64_t *tb_schedule(uint64_t *frame) {\n"; *(const char * *)tb_grow(v_lines) = tb_v982; }
    { const char * tb_v983 = "    tb_cpu *c = tb_me();\n"; *(const char * *)tb_grow(v_lines) = tb_v983; }
    { const char * tb_v984 = "    uint64_t f = tb_irq_save();\n"; *(const char * *)tb_grow(v_lines) = tb_v984; }
    { const char * tb_v985 = "    int cur = c->run;\n"; *(const char * *)tb_grow(v_lines) = tb_v985; }
    { const char * tb_v986 = "    if (cur >= 0) tb_slots[cur].frame = frame; else c->idle_frame = frame;\n"; *(const char * *)tb_grow(v_lines) = tb_v986; }
    { const char * tb_v987 = "    // следующая по кругу: живая и не идущая на другом ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v987; }
