    { const char * tb_v1268 = "// загрузка: заголовок multiboot (флаг 2: «скажи, сколько памяти»). _start работает ещё в 32 битах:\n"; *(const char * *)tb_grow(v_lines) = tb_v1268; }
    { const char * tb_v1269 = "// строит таблицы страниц на первые 4 ГБ, включает режим 64 бит и прыгает в tb_kstart\n"; *(const char * *)tb_grow(v_lines) = tb_v1269; }
