    { const char * tb_v1300 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1300; }
    { const char * tb_v1301 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v1301; }
    { const char * tb_v1302 = "// --- несколько ядер процессора («звёзды») ---\n"; *(const char * *)tb_grow(v_lines) = tb_v1302; }
    { const char * tb_v1303 = "// Какие ядра есть — из таблицы ACPI «APIC» (MADT). Каждое будим так: INIT, потом дважды\n"; *(const char * *)tb_grow(v_lines) = tb_v1303; }
    { const char * tb_v1304 = "// SIPI с адресом 0x8000; там маленький код (ниже) переводит ядро из 16 бит сразу в 64\n"; *(const char * *)tb_grow(v_lines) = tb_v1304; }
    { const char * tb_v1305 = "// и прыгает в tb_ap_main со своим стеком.\n"; *(const char * *)tb_grow(v_lines) = tb_v1305; }
    { const char * tb_v1306 = "TB_API int tb_apic_ids[TB_NCPU];\n"; *(const char * *)tb_grow(v_lines) = tb_v1306; }
    { const char * tb_v1307 = "// таблицы ACPI лежат выше памяти, которую назвал загрузчик: показываем их кусок 2 МБ (только читать)\n"; *(const char * *)tb_grow(v_lines) = tb_v1307; }
    { const char * tb_v1308 = "TB_API void tb_map_2m(uint64_t a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1308; }
    { const char * tb_v1309 = "    if (a >= (4ull << 30) || a < (uint64_t)(uintptr_t)tb_heap_area) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1309; }
    { const char * tb_v1310 = "    uint64_t *e = &tb_pdir[a >> 30][(a >> 21) & 511];\n"; *(const char * *)tb_grow(v_lines) = tb_v1310; }
    { const char * tb_v1311 = "    if (*e) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v1311; }
    { const char * tb_v1312 = "    tb_pdpt[a >> 30] = (uint64_t)(uintptr_t)tb_pdir[a >> 30] | 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v1312; }
    { const char * tb_v1313 = "    *e = (a & ~0x1FFFFFull) | 0x81;\n"; *(const char * *)tb_grow(v_lines) = tb_v1313; }
    { const char * tb_v1314 = "    __asm__ volatile(\"invlpg (%0)\" : : \"r\"(a) : \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1314; }
    { const char * tb_v1315 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1315; }
    { const char * tb_v1316 = "TB_API int tb_find_cpus(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1316; }
    { const char * tb_v1317 = "    unsigned char *rsdp = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1317; }
    { const char * tb_v1318 = "    for (uint64_t a = 0xE0000; a < 0x100000 && !rsdp; a += 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v1318; }
    { const char * tb_v1319 = "        if (memcmp((void *)(uintptr_t)a, \"RSD PTR \", 8) == 0) rsdp = (unsigned char *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v1319; }
    { const char * tb_v1320 = "    if (!rsdp) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1320; }
    { const char * tb_v1321 = "    unsigned char *rsdt = (unsigned char *)(uintptr_t)*(uint32_t *)(rsdp + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v1321; }
    { const char * tb_v1322 = "    tb_map_2m((uint64_t)(uintptr_t)rsdt);\n"; *(const char * *)tb_grow(v_lines) = tb_v1322; }
    { const char * tb_v1323 = "    uint32_t len = *(uint32_t *)(rsdt + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v1323; }
    { const char * tb_v1324 = "    int n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1324; }
    { const char * tb_v1325 = "    for (uint32_t o = 36; o + 4 <= len; o += 4) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1325; }
    { const char * tb_v1326 = "        unsigned char *t = (unsigned char *)(uintptr_t)*(uint32_t *)(rsdt + o);\n"; *(const char * *)tb_grow(v_lines) = tb_v1326; }
    { const char * tb_v1327 = "        tb_map_2m((uint64_t)(uintptr_t)t);\n"; *(const char * *)tb_grow(v_lines) = tb_v1327; }
    { const char * tb_v1328 = "        if (memcmp(t, \"APIC\", 4) != 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v1328; }
    { const char * tb_v1329 = "        uint32_t tl = *(uint32_t *)(t + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v1329; }
    { const char * tb_v1330 = "        for (uint32_t e = 44; e + 2 <= tl && n < TB_NCPU; e += t[e + 1]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1330; }
    { const char * tb_v1331 = "            if (t[e + 1] < 2) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v1331; }
    { const char * tb_v1332 = "            if (t[e] == 0 && (t[e + 4] & 1)) tb_apic_ids[n++] = t[e + 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v1332; }
    { const char * tb_v1333 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v1333; }
    { const char * tb_v1334 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1334; }
    { const char * tb_v1335 = "    return n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1335; }
    { const char * tb_v1336 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1336; }
    { const char * tb_v1337 = "// код пробуждения: копируется в 0x8000; адреса внутри считаются от 0x8000\n"; *(const char * *)tb_grow(v_lines) = tb_v1337; }
    { const char * tb_v1338 = "extern char tb_tramp[], tb_tramp_end[];\n"; *(const char * *)tb_grow(v_lines) = tb_v1338; }
    { const char * tb_v1339 = "TB_API volatile uint64_t tb_ap_stack = 0, tb_ap_cr3 = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1339; }
    { const char * tb_v1340 = "TB_API volatile int tb_ap_up = 0, tb_ap_id = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1340; }
    { const char * tb_v1341 = "__asm__(\".text\\n.global tb_tramp\\n.global tb_tramp_end\\n.global tb_tr_cr3\\n.global tb_tr_stack\\n.code16\\ntb_tramp:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1341; }
    { const char * tb_v1342 = "        \"  cli\\n  xorw %ax, %ax\\n  movw %ax, %ds\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1342; }
    { const char * tb_v1343 = "        \"  lgdtl 0x8000 + (tb_tr_gdtr - tb_tramp)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1343; }
    { const char * tb_v1344 = "        \"  movl %cr0, %eax\\n  orl $1, %eax\\n  movl %eax, %cr0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1344; }
    { const char * tb_v1345 = "        \"  ljmpl $0x08, $(0x8000 + (tb_tr32 - tb_tramp))\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1345; }
    { const char * tb_v1346 = "        \".code32\\ntb_tr32:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1346; }
    { const char * tb_v1347 = "        \"  movw $0x10, %ax\\n  movw %ax, %ds\\n  movw %ax, %ss\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1347; }
    { const char * tb_v1348 = "        \"  movl %cr4, %eax\\n  orl $0x620, %eax\\n  movl %eax, %cr4\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1348; }
    { const char * tb_v1349 = "        \"  movl 0x8000 + (tb_tr_cr3 - tb_tramp), %eax\\n  movl %eax, %cr3\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1349; }
    { const char * tb_v1350 = "        \"  movl $0xC0000080, %ecx\\n  rdmsr\\n  orl $0x100, %eax\\n  wrmsr\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1350; }
    { const char * tb_v1351 = "        \"  movl %cr0, %eax\\n  andl $0xFFFFFFFB, %eax\\n  orl $0x80010002, %eax\\n  movl %eax, %cr0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1351; }
    { const char * tb_v1352 = "        \"  ljmpl $0x18, $(0x8000 + (tb_tr64 - tb_tramp))\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1352; }
    { const char * tb_v1353 = "        \".code64\\ntb_tr64:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1353; }
    { const char * tb_v1354 = "        \"  movq 0x8000 + (tb_tr_stack - tb_tramp), %rsp\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1354; }
    { const char * tb_v1355 = "        \"  movabsq $tb_ap_main, %rax\\n  call *%rax\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1355; }
    { const char * tb_v1356 = "        \"1:\\n  cli\\n  hlt\\n  jmp 1b\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1356; }
    { const char * tb_v1357 = "        \".balign 8\\ntb_tr_gdt:\\n  .quad 0, 0x00CF9A000000FFFF, 0x00CF92000000FFFF, 0x00AF9A000000FFFF\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1357; }
    { const char * tb_v1358 = "        \"tb_tr_gdtr:\\n  .word 31\\n  .long 0x8000 + (tb_tr_gdt - tb_tramp)\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1358; }
    { const char * tb_v1359 = "        \".balign 8\\ntb_tr_cr3:\\n  .quad 0\\ntb_tr_stack:\\n  .quad 0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1359; }
    { const char * tb_v1360 = "        \"tb_tramp_end:\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1360; }
    { const char * tb_v1361 = "TB_API void tb_lapic_timer_start(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1361; }
    { const char * tb_v1362 = "    tb_lapic_w(0x3E0, 3);                              // делитель 16\n"; *(const char * *)tb_grow(v_lines) = tb_v1362; }
    { const char * tb_v1363 = "    tb_lapic_w(0x320, 49 | 0x20000);                   // вектор 49, по кругу\n"; *(const char * *)tb_grow(v_lines) = tb_v1363; }
    { const char * tb_v1364 = "    tb_lapic_w(0x380, tb_lapic_ms);\n"; *(const char * *)tb_grow(v_lines) = tb_v1364; }
    { const char * tb_v1365 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1365; }
    { const char * tb_v1366 = "TB_API void tb_load_tables(int i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1366; }
    { const char * tb_v1367 = "    tb_gdtr.lim = sizeof tb_gdt - 1; tb_gdtr.base = (uint64_t)(uintptr_t)tb_gdt;\n"; *(const char * *)tb_grow(v_lines) = tb_v1367; }
    { const char * tb_v1368 = "    __asm__ volatile(\"lgdt %0\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1368; }
    { const char * tb_v1369 = "                     \"pushq $0x08\\nleaq 1f(%%rip), %%rax\\npushq %%rax\\nlretq\\n1:\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1369; }
    { const char * tb_v1370 = "                     \"movw $0x10, %%ax\\nmovw %%ax, %%ds\\nmovw %%ax, %%es\\nmovw %%ax, %%fs\\nmovw %%ax, %%gs\\nmovw %%ax, %%ss\\n\"\n"; *(const char * *)tb_grow(v_lines) = tb_v1370; }
    { const char * tb_v1371 = "                     : : \"m\"(tb_gdtr) : \"rax\", \"memory\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1371; }
    { const char * tb_v1372 = "    __asm__ volatile(\"ltr %w0\" : : \"r\"(0x18 + 16 * i));\n"; *(const char * *)tb_grow(v_lines) = tb_v1372; }
    { const char * tb_v1373 = "    __asm__ volatile(\"lidt %0\" : : \"m\"(tb_idtr));\n"; *(const char * *)tb_grow(v_lines) = tb_v1373; }
    { const char * tb_v1374 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1374; }
    { const char * tb_v1375 = "// ядро процессора проснулось: свои сегменты, своя запись, таймер APIC — и в пустой ход\n"; *(const char * *)tb_grow(v_lines) = tb_v1375; }
    { const char * tb_v1376 = "__attribute__((used, noreturn)) TB_API void tb_ap_main(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1376; }
    { const char * tb_v1377 = "    int i = tb_ap_id;\n"; *(const char * *)tb_grow(v_lines) = tb_v1377; }
    { const char * tb_v1378 = "    tb_cpu *c = &tb_cpus[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v1378; }
    { const char * tb_v1379 = "    c->self = c;\n"; *(const char * *)tb_grow(v_lines) = tb_v1379; }
    { const char * tb_v1380 = "    tb_set_gs(c);\n"; *(const char * *)tb_grow(v_lines) = tb_v1380; }
    { const char * tb_v1381 = "    __asm__ volatile(\"fninit\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1381; }
    { const char * tb_v1382 = "    tb_load_tables(i);\n"; *(const char * *)tb_grow(v_lines) = tb_v1382; }
    { const char * tb_v1383 = "    tb_set_gs(c);\n"; *(const char * *)tb_grow(v_lines) = tb_v1383; }
    { const char * tb_v1384 = "    tb_set_fs(tb_tls_tp(c->irq_tls));\n"; *(const char * *)tb_grow(v_lines) = tb_v1384; }
    { const char * tb_v1385 = "    tb_lapic_w(0xF0, 0x100 | 48);                      // APIC включён; ложные прерывания — как «уступить ход»\n"; *(const char * *)tb_grow(v_lines) = tb_v1385; }
    { const char * tb_v1386 = "    tb_lapic_timer_start();\n"; *(const char * *)tb_grow(v_lines) = tb_v1386; }
