    { const char * tb_v1388 = "    tb_idle();\n"; *(const char * *)tb_grow(v_lines) = tb_v1388; }
    { const char * tb_v1389 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1389; }
    { const char * tb_v1390 = "TB_API void tb_spin_ms(uint64_t n) { uint64_t end = tb_ms + n; while (tb_ms < end) __asm__ volatile(\"pause\"); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1390; }
    { const char * tb_v1391 = "TB_API void tb_smp_start(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1391; }
    { const char * tb_v1392 = "    // такты APIC за 10 мс (по таймеру PIT, он уже идёт)\n"; *(const char * *)tb_grow(v_lines) = tb_v1392; }
    { const char * tb_v1393 = "    tb_lapic_w(0xF0, 0x100 | 48);\n"; *(const char * *)tb_grow(v_lines) = tb_v1393; }
