    { const char * tb_v1395 = "    tb_lapic_w(0x320, 0x10000 | 49);                   // пока без прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v1395; }
    { const char * tb_v1396 = "    uint64_t t0 = tb_ms; while (tb_ms == t0) __asm__ volatile(\"pause\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1396; }
