    { const char * tb_v1762 = "// поток background или ядра: сначала ставим защиту стека, потом сама работа\n"; *(const char * *)tb_grow(v_lines) = tb_v1762; }
    { const char * tb_v1763 = "// сколько потоков background / ядер работает сейчас: уборка памяти ждёт, пока их нет\n"; *(const char * *)tb_grow(v_lines) = tb_v1763; }
    { const char * tb_v1764 = "TB_API int tb_gthreads = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1764; }
