    { const char * tb_v1766 = "#if defined(__x86_64__) || defined(__i386__)\n"; *(const char * *)tb_grow(v_lines) = tb_v1766; }
    { const char * tb_v1767 = "#define __builtin_ia32_pause_or_yield() __builtin_ia32_pause()\n"; *(const char * *)tb_grow(v_lines) = tb_v1767; }
