    { const char * tb_v1848 = "    SetUnhandledExceptionFilter(tb_win_crashed);\n"; *(const char * *)tb_grow(v_lines) = tb_v1848; }
    { const char * tb_v1849 = "    SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);\n"; *(const char * *)tb_grow(v_lines) = tb_v1849; }
    { const char * tb_v1850 = "    ULONG g = 65536;\n"; *(const char * *)tb_grow(v_lines) = tb_v1850; }
    { const char * tb_v1851 = "    SetThreadStackGuarantee(&g);\n"; *(const char * *)tb_grow(v_lines) = tb_v1851; }
    { const char * tb_v1852 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1852; }
    { const char * tb_v1853 = "    tb_main_sp = &here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1853; }
    { const char * tb_v1854 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1854; }
    { const char * tb_v1855 = "// main() зовёт tb_guard_init(): на Windows ей нужны ещё argc и argv из main\n"; *(const char * *)tb_grow(v_lines) = tb_v1855; }
    { const char * tb_v1856 = "#define tb_guard_init() tb_win_init(&argc, &argv)\n"; *(const char * *)tb_grow(v_lines) = tb_v1856; }
    { const char * tb_v1857 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v1857; }
    { const char * tb_v1858 = "TB_API void tb_guard_init(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1858; }
    { const char * tb_v1859 = "    static char alt[65536];\n"; *(const char * *)tb_grow(v_lines) = tb_v1859; }
    { const char * tb_v1860 = "    stack_t ss;\n"; *(const char * *)tb_grow(v_lines) = tb_v1860; }
