    { const char * tb_v1862 = "    sigaltstack(&ss, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1862; }
    { const char * tb_v1863 = "    struct sigaction sa;\n"; *(const char * *)tb_grow(v_lines) = tb_v1863; }
    { const char * tb_v1864 = "    memset(&sa, 0, sizeof sa);\n"; *(const char * *)tb_grow(v_lines) = tb_v1864; }
    { const char * tb_v1865 = "    sa.sa_sigaction = tb_on_segv;\n"; *(const char * *)tb_grow(v_lines) = tb_v1865; }
    { const char * tb_v1866 = "    sa.sa_flags = SA_SIGINFO | SA_ONSTACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v1866; }
    { const char * tb_v1867 = "    sigaction(SIGSEGV, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1867; }
    { const char * tb_v1868 = "    sigaction(SIGBUS, &sa, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1868; }
    { const char * tb_v1869 = "    char here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1869; }
    { const char * tb_v1870 = "    tb_main_sp = &here;\n"; *(const char * *)tb_grow(v_lines) = tb_v1870; }
    { const char * tb_v1871 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1871; }
    { const char * tb_v1872 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1872; }
    { const char * tb_v1873 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v1873; }
    { const char * tb_v1874 = "// ---------- temp: временная память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1874; }
    { const char * tb_v1875 = "// Внутри блока temp память берётся из больших кусков подряд (быстро, без malloc),\n"; *(const char * *)tb_grow(v_lines) = tb_v1875; }
    { const char * tb_v1876 = "// а в конце блока все куски отдаются разом. У каждого ядра свои куски.\n"; *(const char * *)tb_grow(v_lines) = tb_v1876; }
    { const char * tb_v1877 = "typedef struct { char *mem; long long size, used; } tb_chunk;\n"; *(const char * *)tb_grow(v_lines) = tb_v1877; }
    { const char * tb_v1878 = "typedef struct { int n; long long used; } tb_mark;\n"; *(const char * *)tb_grow(v_lines) = tb_v1878; }
    { const char * tb_v1879 = "TB_API _Thread_local tb_chunk *tb_chunks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1879; }
    { const char * tb_v1880 = "TB_API _Thread_local int tb_nchunks = 0, tb_capchunks = 0, tb_temp_depth = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1880; }
    { const char * tb_v1881 = "TB_API int tb_in_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1881; }
    { const char * tb_v1882 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1882; }
    { const char * tb_v1883 = "        if ((const char *)p >= tb_chunks[i].mem && (const char *)p < tb_chunks[i].mem + tb_chunks[i].size) return 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1883; }
    { const char * tb_v1884 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1884; }
    { const char * tb_v1885 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1885; }
    { const char * tb_v1886 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1886; }
    { const char * tb_v1887 = "TB_API void *tb_temp_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1887; }
    { const char * tb_v1888 = "    n = n > 0 ? (n + 15) & ~15LL : 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1888; }
    { const char * tb_v1889 = "    tb_chunk *c = tb_nchunks > 0 ? &tb_chunks[tb_nchunks - 1] : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1889; }
    { const char * tb_v1890 = "    if (c == 0 || c->used + n > c->size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1890; }
    { const char * tb_v1891 = "        long long size = c != 0 ? c->size * 2 : (1LL << 20);\n"; *(const char * *)tb_grow(v_lines) = tb_v1891; }
    { const char * tb_v1892 = "        if (size < n) size = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1892; }
    { const char * tb_v1893 = "        if (tb_nchunks == tb_capchunks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1893; }
    { const char * tb_v1894 = "            tb_capchunks = tb_capchunks * 2 + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v1894; }
    { const char * tb_v1895 = "            tb_chunks = realloc(tb_chunks, sizeof(tb_chunk) * tb_capchunks);\n"; *(const char * *)tb_grow(v_lines) = tb_v1895; }
    { const char * tb_v1896 = "            if (tb_chunks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1896; }
    { const char * tb_v1897 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v1897; }
    { const char * tb_v1898 = "        char *mem = malloc(size);\n"; *(const char * *)tb_grow(v_lines) = tb_v1898; }
    { const char * tb_v1899 = "        if (mem == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1899; }
    { const char * tb_v1900 = "        tb_chunks[tb_nchunks] = (tb_chunk){mem, size, 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v1900; }
    { const char * tb_v1901 = "        c = &tb_chunks[tb_nchunks];\n"; *(const char * *)tb_grow(v_lines) = tb_v1901; }
    { const char * tb_v1902 = "        tb_nchunks += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1902; }
    { const char * tb_v1903 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1903; }
    { const char * tb_v1904 = "    void *p = c->mem + c->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v1904; }
    { const char * tb_v1905 = "    c->used += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1905; }
    { const char * tb_v1906 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1906; }
    { const char * tb_v1907 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1907; }
    { const char * tb_v1908 = "// метки открытых temp (и арен шага / функции): самая последняя — текущая область\n"; *(const char * *)tb_grow(v_lines) = tb_v1908; }
    { const char * tb_v1909 = "TB_API _Thread_local tb_mark *tb_marks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1909; }
    { const char * tb_v1910 = "TB_API _Thread_local int tb_capmarks = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1910; }
    { const char * tb_v1911 = "TB_INL tb_mark tb_temp_begin(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1911; }
    { const char * tb_v1912 = "    tb_mark m = {tb_nchunks, tb_nchunks > 0 ? tb_chunks[tb_nchunks - 1].used : 0};\n"; *(const char * *)tb_grow(v_lines) = tb_v1912; }
    { const char * tb_v1913 = "    if (tb_temp_depth == tb_capmarks) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1913; }
    { const char * tb_v1914 = "        tb_capmarks = tb_capmarks * 2 + 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v1914; }
    { const char * tb_v1915 = "        tb_marks = realloc(tb_marks, sizeof(tb_mark) * tb_capmarks);\n"; *(const char * *)tb_grow(v_lines) = tb_v1915; }
    { const char * tb_v1916 = "        if (tb_marks == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1916; }
    { const char * tb_v1917 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1917; }
    { const char * tb_v1918 = "    tb_marks[tb_temp_depth] = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1918; }
    { const char * tb_v1919 = "    tb_temp_depth += 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1919; }
    { const char * tb_v1920 = "    return m;\n"; *(const char * *)tb_grow(v_lines) = tb_v1920; }
    { const char * tb_v1921 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1921; }
    { const char * tb_v1922 = "// p во временной памяти текущей (самой внутренней) области, а не во внешней\n"; *(const char * *)tb_grow(v_lines) = tb_v1922; }
    { const char * tb_v1923 = "TB_API int tb_in_cur_temp(const void *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1923; }
    { const char * tb_v1924 = "    if (tb_temp_depth == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1924; }
    { const char * tb_v1925 = "    tb_mark t = tb_marks[tb_temp_depth - 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v1925; }
    { const char * tb_v1926 = "    for (int i = tb_nchunks - 1; i >= 0; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1926; }
    { const char * tb_v1927 = "        const char *m = tb_chunks[i].mem;\n"; *(const char * *)tb_grow(v_lines) = tb_v1927; }
    { const char * tb_v1928 = "        if ((const char *)p >= m && (const char *)p < m + tb_chunks[i].size)\n"; *(const char * *)tb_grow(v_lines) = tb_v1928; }
    { const char * tb_v1929 = "            return i > t.n - 1 || (i == t.n - 1 && (const char *)p - m >= t.used);\n"; *(const char * *)tb_grow(v_lines) = tb_v1929; }
    { const char * tb_v1930 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1930; }
    { const char * tb_v1931 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1931; }
    { const char * tb_v1932 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1932; }
    { const char * tb_v1933 = "// длина последних текстов: s[i] в цикле не пересчитывает strlen каждый раз\n"; *(const char * *)tb_grow(v_lines) = tb_v1933; }
    { const char * tb_v1934 = "TB_API _Thread_local const char *tb_lc_p[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1934; }
    { const char * tb_v1935 = "TB_API _Thread_local long long tb_lc_n[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v1935; }
    { const char * tb_v1936 = "TB_API _Thread_local int tb_lc_next;\n"; *(const char * *)tb_grow(v_lines) = tb_v1936; }
    { const char * tb_v1937 = "TB_INL void tb_lc_clear(void) { tb_lc_p[0] = 0; tb_lc_p[1] = 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1937; }
    { const char * tb_v1938 = "TB_INL void tb_temp_end(tb_mark m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1938; }
    { const char * tb_v1939 = "    // первый кусок оставляем пустым: следующий temp возьмёт его без malloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1939; }
    { const char * tb_v1940 = "    while (tb_nchunks > m.n && tb_nchunks > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1940; }
    { const char * tb_v1941 = "        tb_nchunks -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1941; }
    { const char * tb_v1942 = "        free(tb_chunks[tb_nchunks].mem);\n"; *(const char * *)tb_grow(v_lines) = tb_v1942; }
    { const char * tb_v1943 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v1943; }
    { const char * tb_v1944 = "    if (tb_nchunks > m.n) tb_chunks[0].used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v1944; }
    { const char * tb_v1945 = "    else if (tb_nchunks > 0) tb_chunks[tb_nchunks - 1].used = m.used;\n"; *(const char * *)tb_grow(v_lines) = tb_v1945; }
    { const char * tb_v1946 = "    tb_temp_depth -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v1946; }
    { const char * tb_v1947 = "    tb_lc_clear();\n"; *(const char * *)tb_grow(v_lines) = tb_v1947; }
    { const char * tb_v1948 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1948; }
    { const char * tb_v1949 = "// --llvm: то же через указатель (из файла .ll так проще, чем отдавать struct по значению)\n"; *(const char * *)tb_grow(v_lines) = tb_v1949; }
    { const char * tb_v1950 = "TB_INL void tb_temp_begin_p(tb_mark *m) { *m = tb_temp_begin(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1950; }
    { const char * tb_v1951 = "TB_INL void tb_temp_end_p(tb_mark *m) { tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1951; }
    { const char * tb_v1952 = "// память функции: своя область, только если функцию позвали не изнутри другой области\n"; *(const char * *)tb_grow(v_lines) = tb_v1952; }
    { const char * tb_v1953 = "TB_INL int tb_fa_begin(tb_mark *m) { if (tb_temp_depth != 0) return 0; *m = tb_temp_begin(); return 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v1953; }
    { const char * tb_v1954 = "TB_INL void tb_fa_end(int fa, tb_mark *m) { if (fa) tb_temp_end(*m); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1954; }
    { const char * tb_v1955 = "// ---------- уборка памяти: сборщик мусора ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v1955; }
    { const char * tb_v1956 = "// Шаги циклов, функции и temp уже отдают память сами (своя временная память).\n"; *(const char * *)tb_grow(v_lines) = tb_v1956; }
    { const char * tb_v1957 = "// А то, что живёт дольше (obj, списки, dict, тексты), раньше жило до конца программы.\n"; *(const char * *)tb_grow(v_lines) = tb_v1957; }
    { const char * tb_v1958 = "// Теперь иногда (когда набралось много новой памяти) программа делает обход:\n"; *(const char * *)tb_grow(v_lines) = tb_v1958; }
    { const char * tb_v1959 = "//   1) смотрит, что видно из переменных: стек, общие (shared) переменные, временная память;\n"; *(const char * *)tb_grow(v_lines) = tb_v1959; }
    { const char * tb_v1960 = "//   2) от них идёт по всему, на что они указывают, и помечает это «нужно»;\n"; *(const char * *)tb_grow(v_lines) = tb_v1960; }
    { const char * tb_v1961 = "//   3) всё не помеченное — мусор, его место отдаётся под новые значения.\n"; *(const char * *)tb_grow(v_lines) = tb_v1961; }
    { const char * tb_v1962 = "// Обход идёт, только когда работает один поток: пока идут background или on all cores, ждём.\n"; *(const char * *)tb_grow(v_lines) = tb_v1962; }
    { const char * tb_v1963 = "// TB_GC=0 — выключить уборку (для проверки), TB_GC_STRESS=N — обход на каждом N-м выделении,\n"; *(const char * *)tb_grow(v_lines) = tb_v1963; }
    { const char * tb_v1964 = "// TB_GC_STATS=1 — печатать каждый обход.\n"; *(const char * *)tb_grow(v_lines) = tb_v1964; }
    { const char * tb_v1965 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v1965; }
    { const char * tb_v1966 = "TB_API void *tb_gc_alloc(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1966; }
    { const char * tb_v1967 = "    void *p = malloc(n > 0 ? n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1967; }
    { const char * tb_v1968 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1968; }
    { const char * tb_v1969 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1969; }
    { const char * tb_v1970 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1970; }
    { const char * tb_v1971 = "TB_API void tb_gc_free(void *p) { free(p); }\n"; *(const char * *)tb_grow(v_lines) = tb_v1971; }
    { const char * tb_v1972 = "#define tb_gc_alloc_np tb_gc_alloc\n"; *(const char * *)tb_grow(v_lines) = tb_v1972; }
    { const char * tb_v1973 = "TB_API void *tb_gc_realloc(void *p, long long old_n, long long new_n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v1973; }
    { const char * tb_v1974 = "    (void)old_n;\n"; *(const char * *)tb_grow(v_lines) = tb_v1974; }
    { const char * tb_v1975 = "    p = realloc(p, new_n > 0 ? new_n : 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v1975; }
    { const char * tb_v1976 = "    if (p == 0) tb_crash(0, \"не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v1976; }
    { const char * tb_v1977 = "    return p;\n"; *(const char * *)tb_grow(v_lines) = tb_v1977; }
    { const char * tb_v1978 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v1978; }
    { const char * tb_v1979 = "#define tb_gc_root(p, n) ((void)(p), (void)(n))\n"; *(const char * *)tb_grow(v_lines) = tb_v1979; }
