    { const char * tb_v2098 = "    return pg;\n"; *(const char * *)tb_grow(v_lines) = tb_v2098; }
    { const char * tb_v2099 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2099; }
    { const char * tb_v2100 = "#define TB_GIDX(pg, off) ((long long)(((unsigned long long)(off) * (pg)->inv) >> 32))\n"; *(const char * *)tb_grow(v_lines) = tb_v2100; }
    { const char * tb_v2101 = "// блок, внутрь которого указывает адрес a (или 0, если это не наша занятая память)\n"; *(const char * *)tb_grow(v_lines) = tb_v2101; }
    { const char * tb_v2102 = "TB_INL char *tb_gblock(uintptr_t a, tb_gpage **out) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2102; }
    { const char * tb_v2103 = "    if (a < tb_glo || a >= tb_ghi) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2103; }
