    { const char * tb_v2115 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v2115; }
    { const char * tb_v2116 = "TB_API void tb_gc_collect(void);\n"; *(const char * *)tb_grow(v_lines) = tb_v2116; }
