    { const char * tb_v2330 = "TB_API void tb_gc_collect(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2330; }
    { const char * tb_v2331 = "    tb_gruns++;\n"; *(const char * *)tb_grow(v_lines) = tb_v2331; }
    { const char * tb_v2332 = "    double t0 = tb_gstats ? tb_gnow() : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2332; }
