    { const char * tb_v2338 = "    for (int c = 0; c < TB_GNC; c++) { tb_gavail[0][c] = 0; tb_gavail[1][c] = 0; keep_empty[c] = 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2338; }
    { const char * tb_v2339 = "    tb_gpage **pp = &tb_gall;\n"; *(const char * *)tb_grow(v_lines) = tb_v2339; }
