    { const char * tb_v2341 = "        tb_gpage *pg = *pp;\n"; *(const char * *)tb_grow(v_lines) = tb_v2341; }
    { const char * tb_v2342 = "        long long used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2342; }
