    { const char * tb_v2344 = "        long long i = pg->bump - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2344; }
    { const char * tb_v2345 = "        // быстрый путь: 8 подряд занятых и нужных блоков — просто снимаем отметки\n"; *(const char * *)tb_grow(v_lines) = tb_v2345; }
    { const char * tb_v2346 = "        long long full = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2346; }
