    { const char * tb_v2350 = "            if (w != 0x0303030303030303ULL) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v2350; }
    { const char * tb_v2351 = "            w = 0x0101010101010101ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v2351; }
