    { const char * tb_v2353 = "            full = k + 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v2353; }
    { const char * tb_v2354 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2354; }
    { const char * tb_v2355 = "        used += full;\n"; *(const char * *)tb_grow(v_lines) = tb_v2355; }
    { const char * tb_v2356 = "        for (; i >= full; i--) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2356; }
