    { const char * tb_v2358 = "            if (pg->fl[i] == 3) { pg->fl[i] = 1; used++; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v2358; }
    { const char * tb_v2359 = "            if (pg->fl[i] & 1) memset(b, 0, pg->bsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2359; }
