    { const char * tb_v2365 = "            tb_gmap_remove(pg, TB_GPG);\n"; *(const char * *)tb_grow(v_lines) = tb_v2365; }
    { const char * tb_v2366 = "            // страница — в запас, чистой (в свободных блоках лежали ссылки на соседей)\n"; *(const char * *)tb_grow(v_lines) = tb_v2366; }
    { const char * tb_v2367 = "            memset(pg->start, 0, pg->bump * pg->bsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v2367; }
    { const char * tb_v2368 = "            *(void **)pg->start = tb_gspare; tb_gspare = pg->start;\n"; *(const char * *)tb_grow(v_lines) = tb_v2368; }
    { const char * tb_v2369 = "            free(pg->fl); free(pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v2369; }
