    { const char * tb_v2371 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2371; }
    { const char * tb_v2372 = "        if (used == 0) keep_empty[pg->cls]--;\n"; *(const char * *)tb_grow(v_lines) = tb_v2372; }
    { const char * tb_v2373 = "        live += used * pg->bsize;\n"; *(const char * *)tb_grow(v_lines) = tb_v2373; }
    { const char * tb_v2374 = "        pg->in_avail = pg->nfree > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2374; }
