    { const char * tb_v2378 = "    tb_gpage *pg = tb_glarge;\n"; *(const char * *)tb_grow(v_lines) = tb_v2378; }
    { const char * tb_v2379 = "    while (pg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2379; }
    { const char * tb_v2380 = "        tb_gpage *nx = pg->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v2380; }
    { const char * tb_v2381 = "        if (!(pg->lfl & 2)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2381; }
