    { const char * tb_v2386 = "            free(pg);\n"; *(const char * *)tb_grow(v_lines) = tb_v2386; }
    { const char * tb_v2387 = "        } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v2387; }
    { const char * tb_v2388 = "            pg->lfl = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2388; }
    { const char * tb_v2389 = "            live += pg->cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2389; }
    { const char * tb_v2390 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v2390; }
    { const char * tb_v2391 = "        pg = nx;\n"; *(const char * *)tb_grow(v_lines) = tb_v2391; }
    { const char * tb_v2392 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2392; }
    { const char * tb_v2393 = "    tb_lc_clear();   // длины текстов по адресу: адрес мог достаться новому тексту\n"; *(const char * *)tb_grow(v_lines) = tb_v2393; }
    { const char * tb_v2394 = "    long long before = tb_glive + tb_gsince;\n"; *(const char * *)tb_grow(v_lines) = tb_v2394; }
    { const char * tb_v2395 = "    tb_glive = live;\n"; *(const char * *)tb_grow(v_lines) = tb_v2395; }
    { const char * tb_v2396 = "    tb_gsince = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "    // следующий обход — когда новой памяти станет вдвое больше нужной\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "    // если мусора почти не нашлось (программа копит данные), следующий обход — ещё позже\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "    // если мусора почти не нашлось (программа копит данные) два раза подряд — ещё реже (×8),\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
    { const char * tb_v2400 = "    // но лишней памяти сверх «вдвое» не больше 512 МБ\n"; *(const char * *)tb_grow(v_lines) = tb_v2400; }
    { const char * tb_v2401 = "    static int tb_gkeep = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v2401; }
