    { const char * tb_v2403 = "    long long k = tb_gkeep >= 2 ? 8 : (live * 4 > before * 3 ? 4 : 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v2403; }
    { const char * tb_v2404 = "    long long next = k * live;\n"; *(const char * *)tb_grow(v_lines) = tb_v2404; }
