    { const char * tb_v2504 = "    long long words = (n + 63) / 64 + (n == 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2504; }
    { const char * tb_v2505 = "    l->len = n; l->cap = words * 64; l->size = 0; l->data = tb_mem_np(words * 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v2505; }
