    { const char * tb_v2539 = "// N одинаковых битов в конец (repeat N times: flags.add(true))\n"; *(const char * *)tb_grow(v_lines) = tb_v2539; }
    { const char * tb_v2540 = "TB_API void tb_bfill(tb_list *l, long long n, _Bool v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2540; }
    { const char * tb_v2541 = "    if (n <= 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v2541; }
    { const char * tb_v2542 = "    if (l->cap < 0) tb_crash(0, \"список нельзя растить, пока по нему идёт each ... by N (и сам кусок растить нельзя)\");\n"; *(const char * *)tb_grow(v_lines) = tb_v2542; }
    { const char * tb_v2543 = "    long long need = l->len + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v2543; }
    { const char * tb_v2544 = "    if (need > l->cap) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2544; }
    { const char * tb_v2545 = "        long long old = l->cap / 8, cap = l->cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2545; }
    { const char * tb_v2546 = "        while (cap < need) cap *= 2;\n"; *(const char * *)tb_grow(v_lines) = tb_v2546; }
