    { const char * tb_v2568 = "        l->cap = cap;\n"; *(const char * *)tb_grow(v_lines) = tb_v2568; }
    { const char * tb_v2569 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v2569; }
    { const char * tb_v2570 = "    char *p = l->data + l->len * l->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v2570; }
    { const char * tb_v2571 = "    int zero = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v2571; }
