    { const char * tb_v2924 = "TB_API const char *tb_date_now(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v2924; }
    { const char * tb_v2925 = "    time_t t = time(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v2925; }
    { const char * tb_v2926 = "    struct tm tmv;\n"; *(const char * *)tb_grow(v_lines) = tb_v2926; }
