    { const char * tb_v3134 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3134; }
    { const char * tb_v3135 = "TB_API unsigned long long tb_rand_state = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3135; }
    { const char * tb_v3136 = "// цвет из красного, зелёного и синего (0..255) — одно число 0xRRGGBB\n"; *(const char * *)tb_grow(v_lines) = tb_v3136; }
    { const char * tb_v3137 = "TB_API long long tb_rgb(long long r, long long g, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3137; }
    { const char * tb_v3138 = "    r = r < 0 ? 0 : r > 255 ? 255 : r; g = g < 0 ? 0 : g > 255 ? 255 : g; b = b < 0 ? 0 : b > 255 ? 255 : b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3138; }
    { const char * tb_v3139 = "    return (r << 16) | (g << 8) | b;\n"; *(const char * *)tb_grow(v_lines) = tb_v3139; }
    { const char * tb_v3140 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3140; }
    { const char * tb_v3141 = "// цвет с непрозрачностью a: 255 — сплошной (как rgb), 0 — не виден. Рисование смешивает его с тем, что под ним\n"; *(const char * *)tb_grow(v_lines) = tb_v3141; }
    { const char * tb_v3142 = "TB_API long long tb_rgba(long long r, long long g, long long b, long long a) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3142; }
    { const char * tb_v3143 = "    a = a < 0 ? 0 : a > 255 ? 255 : a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3143; }
    { const char * tb_v3144 = "    return ((255 - a) << 24) | tb_rgb(r, g, b);\n"; *(const char * *)tb_grow(v_lines) = tb_v3144; }
    { const char * tb_v3145 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3145; }
    { const char * tb_v3146 = "// случайное целое от a до b (оба входят)\n"; *(const char * *)tb_grow(v_lines) = tb_v3146; }
    { const char * tb_v3147 = "TB_API long long tb_random(long long a, long long b) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3147; }
    { const char * tb_v3148 = "    if (tb_rand_state == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3148; }
    { const char * tb_v3149 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3149; }
    { const char * tb_v3150 = "        unsigned lo, hi; __asm__ volatile(\"rdtsc\" : \"=a\"(lo), \"=d\"(hi));\n"; *(const char * *)tb_grow(v_lines) = tb_v3150; }
    { const char * tb_v3151 = "        tb_rand_state = ((unsigned long long)hi << 32 | lo) ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3151; }
    { const char * tb_v3152 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3152; }
    { const char * tb_v3153 = "        struct timespec ts; clock_gettime(CLOCK_REALTIME, &ts);\n"; *(const char * *)tb_grow(v_lines) = tb_v3153; }
    { const char * tb_v3154 = "        tb_rand_state = ((unsigned long long)ts.tv_nsec << 20) ^ (unsigned long long)ts.tv_sec ^ 0x9E3779B97F4A7C15ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3154; }
    { const char * tb_v3155 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3155; }
    { const char * tb_v3156 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3156; }
    { const char * tb_v3157 = "    if (b < a) { long long t = a; a = b; b = t; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3157; }
    { const char * tb_v3158 = "    tb_rand_state ^= tb_rand_state << 13; tb_rand_state ^= tb_rand_state >> 7; tb_rand_state ^= tb_rand_state << 17;\n"; *(const char * *)tb_grow(v_lines) = tb_v3158; }
    { const char * tb_v3159 = "    unsigned long long span = (unsigned long long)(b - a) + 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3159; }
