    { const char * tb_v3302 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3302; }
    { const char * tb_v3303 = "// --llvm: число ключей (из .ll не надо знать устройство tb_dict)\n"; *(const char * *)tb_grow(v_lines) = tb_v3303; }
    { const char * tb_v3304 = "TB_INL long long tb_dlen(tb_dict *d) { return d->keys->len; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3304; }
    { const char * tb_v3305 = "TB_INL tb_list *tb_dkeys_copy(tb_dict *d) { return tb_copy(d->keys); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3305; }
    { const char * tb_v3306 = "TB_INL tb_list *tb_dvals_copy(tb_dict *d) { return tb_copy(d->vals); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3306; }
    { const char * tb_v3307 = "TB_API void tb_dclear(tb_dict *d, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3307; }
    { const char * tb_v3308 = "    tb_lclear(d->keys, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3308; }
    { const char * tb_v3309 = "    tb_lclear(d->vals, line);\n"; *(const char * *)tb_grow(v_lines) = tb_v3309; }
    { const char * tb_v3310 = "    if (d->pos && !(tb_nchunks > 0 && tb_in_temp(d->pos))) tb_gc_free(d->pos);\n"; *(const char * *)tb_grow(v_lines) = tb_v3310; }
    { const char * tb_v3311 = "    if (d->slots && !(tb_nchunks > 0 && tb_in_temp(d->slots))) tb_gc_free(d->slots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3311; }
    { const char * tb_v3312 = "    d->slots = 0; d->pos = 0; d->npos = 0; d->base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3312; }
