    { const char * tb_v3315 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3315; }
    { const char * tb_v3316 = "// новый ключ int k: можно ли остаться без поиска (mode 1 или 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v3316; }
    { const char * tb_v3317 = "TB_API void tb_dplace_int(tb_dict *d, long long k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3317; }
    { const char * tb_v3318 = "    long long n = d->keys->len;          // уже вместе с новым ключом\n"; *(const char * *)tb_grow(v_lines) = tb_v3318; }
    { const char * tb_v3319 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3319; }
    { const char * tb_v3320 = "        if (n == 1) { d->base = k; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3320; }
    { const char * tb_v3321 = "        if (k == d->base + n - 1) return;  // подряд — остаёмся в mode 1\n"; *(const char * *)tb_grow(v_lines) = tb_v3321; }
    { const char * tb_v3322 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3322; }
    { const char * tb_v3323 = "    if (d->mode == 1 || d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3323; }
    { const char * tb_v3324 = "        // плотно ли: ключи не дальше 4 ячеек на один ключ\n"; *(const char * *)tb_grow(v_lines) = tb_v3324; }
    { const char * tb_v3325 = "        long long o = k - d->base;\n"; *(const char * *)tb_grow(v_lines) = tb_v3325; }
    { const char * tb_v3326 = "        if (o >= 0 && o < 4 * n + 64) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3326; }
    { const char * tb_v3327 = "            if (d->mode == 2 && o < d->npos) { d->pos[o] = n; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3327; }
    { const char * tb_v3328 = "            long long want = d->npos * 2 > o + 1 ? d->npos * 2 : o + 1 + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3328; }
    { const char * tb_v3329 = "            if (want < 16) want = 16;\n"; *(const char * *)tb_grow(v_lines) = tb_v3329; }
    { const char * tb_v3330 = "            tb_dto_pos(d, want);\n"; *(const char * *)tb_grow(v_lines) = tb_v3330; }
    { const char * tb_v3331 = "            return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3331; }
    { const char * tb_v3332 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3332; }
    { const char * tb_v3333 = "        tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3333; }
    { const char * tb_v3334 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3334; }
    { const char * tb_v3335 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3335; }
    { const char * tb_v3336 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3336; }
    { const char * tb_v3337 = "// место под значение ключа k; если ключа нет — добавить со значением *def\n"; *(const char * *)tb_grow(v_lines) = tb_v3337; }
    { const char * tb_v3338 = "TB_API void *tb_dput(tb_dict *d, const void *k, const void *def) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3338; }
    { const char * tb_v3339 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3339; }
    { const char * tb_v3340 = "    if (at >= 0) return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3340; }
    { const char * tb_v3341 = "    memcpy(tb_grow(d->keys), k, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3341; }
    { const char * tb_v3342 = "    void *v = tb_grow(d->vals);\n"; *(const char * *)tb_grow(v_lines) = tb_v3342; }
    { const char * tb_v3343 = "    if (def) memcpy(v, def, d->vals->size); else memset(v, 0, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3343; }
    { const char * tb_v3344 = "    if (d->mode != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3344; }
    { const char * tb_v3345 = "        // без поиска; если ключ лёг далеко, tb_dplace_int сам перейдёт на хеш и впишет все ключи\n"; *(const char * *)tb_grow(v_lines) = tb_v3345; }
    { const char * tb_v3346 = "        tb_dplace_int(d, *(const long long *)k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3346; }
    { const char * tb_v3347 = "        return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3347; }
    { const char * tb_v3348 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3348; }
    { const char * tb_v3349 = "    if (d->keys->len * 2 > d->nslots) tb_dreindex(d, d->nslots * 2);\n"; *(const char * *)tb_grow(v_lines) = tb_v3349; }
    { const char * tb_v3350 = "    else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3350; }
    { const char * tb_v3351 = "        unsigned long long h = tb_hash(d, k), mask = d->nslots - 1, i = h & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3351; }
    { const char * tb_v3352 = "        while (d->slots[i] != 0) i = (i + 1) & mask;\n"; *(const char * *)tb_grow(v_lines) = tb_v3352; }
    { const char * tb_v3353 = "        d->slots[i] = d->keys->len | TB_DTAG(h);\n"; *(const char * *)tb_grow(v_lines) = tb_v3353; }
    { const char * tb_v3354 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3354; }
    { const char * tb_v3355 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v3355; }
    { const char * tb_v3356 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3356; }
    { const char * tb_v3357 = "TB_API void *tb_dget(tb_dict *d, const void *k, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3357; }
    { const char * tb_v3358 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3358; }
    { const char * tb_v3359 = "    if (TB_RARE(at < 0)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3359; }
    { const char * tb_v3360 = "        if (d->text) tb_crash(line, tb_cat(\"в dict нет ключа: \", *(const char * const *)k));\n"; *(const char * *)tb_grow(v_lines) = tb_v3360; }
    { const char * tb_v3361 = "        tb_crash(line, tb_cat(\"в dict нет ключа: \", tb_itos(*(const long long *)k)));\n"; *(const char * *)tb_grow(v_lines) = tb_v3361; }
    { const char * tb_v3362 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3362; }
    { const char * tb_v3363 = "    return d->vals->data + at * d->vals->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3363; }
    { const char * tb_v3364 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3364; }
    { const char * tb_v3365 = "// together: шаг 1 — просим память принести место ключа заранее\n"; *(const char * *)tb_grow(v_lines) = tb_v3365; }
    { const char * tb_v3366 = "TB_INL unsigned long long tb_dpre1(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3366; }
    { const char * tb_v3367 = "    if (d->mode == 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3367; }
    { const char * tb_v3368 = "        unsigned long long at = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3368; }
    { const char * tb_v3369 = "        if (at < (unsigned long long)d->vals->len) __builtin_prefetch(d->vals->data + at * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3369; }
    { const char * tb_v3370 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3370; }
    { const char * tb_v3371 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3371; }
    { const char * tb_v3372 = "    if (d->mode == 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3372; }
    { const char * tb_v3373 = "        unsigned long long o = (unsigned long long)(*(const long long *)k - d->base);\n"; *(const char * *)tb_grow(v_lines) = tb_v3373; }
    { const char * tb_v3374 = "        if (o < (unsigned long long)d->npos) { __builtin_prefetch(&d->pos[o]); return o; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3374; }
    { const char * tb_v3375 = "        return ~0ULL;\n"; *(const char * *)tb_grow(v_lines) = tb_v3375; }
    { const char * tb_v3376 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3376; }
    { const char * tb_v3377 = "    unsigned long long i = tb_hash(d, k) & (d->nslots - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3377; }
    { const char * tb_v3378 = "    __builtin_prefetch(&d->slots[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v3378; }
    { const char * tb_v3379 = "    return i;\n"; *(const char * *)tb_grow(v_lines) = tb_v3379; }
    { const char * tb_v3380 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3380; }
    { const char * tb_v3381 = "// шаг 2 — место приехало: просим принести ключ и значение\n"; *(const char * *)tb_grow(v_lines) = tb_v3381; }
    { const char * tb_v3382 = "TB_INL void tb_dpre2(tb_dict *d, unsigned long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3382; }
    { const char * tb_v3383 = "    if (i == ~0ULL || d->mode == 1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3383; }
    { const char * tb_v3384 = "    long long s = d->mode == 2 ? d->pos[i] : (d->slots[i] & TB_DAT);\n"; *(const char * *)tb_grow(v_lines) = tb_v3384; }
    { const char * tb_v3385 = "    if (s != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3385; }
    { const char * tb_v3386 = "        if (d->mode == 0) __builtin_prefetch(d->keys->data + (s - 1) * d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3386; }
    { const char * tb_v3387 = "        __builtin_prefetch(d->vals->data + (s - 1) * d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3387; }
    { const char * tb_v3388 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3388; }
    { const char * tb_v3389 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3389; }
    { const char * tb_v3390 = "// элемент списка заранее (prefetch за пределами списка ничего не ломает)\n"; *(const char * *)tb_grow(v_lines) = tb_v3390; }
    { const char * tb_v3391 = "TB_INL void tb_lpre(tb_list *l, long long i) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3391; }
    { const char * tb_v3392 = "    __builtin_prefetch(l->data + i * l->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3392; }
    { const char * tb_v3393 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3393; }
    { const char * tb_v3394 = "// ---------- холодные качества obj: своя память, отдельно от горячих ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3394; }
    { const char * tb_v3395 = "TB_API void *tb_cold_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3395; }
    { const char * tb_v3396 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3396; }
    { const char * tb_v3397 = "    void *r = tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3397; }
    { const char * tb_v3398 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3398; }
    { const char * tb_v3399 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3399; }
    { const char * tb_v3400 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3400; }
    { const char * tb_v3401 = "TB_API void *tb_cold_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3401; }
    { const char * tb_v3402 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3402; }
    { const char * tb_v3403 = "    void *r = tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3403; }
    { const char * tb_v3404 = "    memset(r, 0, n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3404; }
    { const char * tb_v3405 = "    return r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3405; }
    { const char * tb_v3406 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3406; }
    { const char * tb_v3407 = "// ---------- obj: память ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3407; }
    { const char * tb_v3408 = "// Внутри temp и шага цикла — из временной памяти, иначе — из памяти с уборкой.\n"; *(const char * *)tb_grow(v_lines) = tb_v3408; }
    { const char * tb_v3409 = "TB_API void *tb_obj_mem(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3409; }
    { const char * tb_v3410 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3410; }
    { const char * tb_v3411 = "    return tb_gc_alloc(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3411; }
    { const char * tb_v3412 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3412; }
    { const char * tb_v3413 = "TB_API void *tb_obj_mem_np(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3413; }
    { const char * tb_v3414 = "    if (tb_temp_depth > 0) return tb_mem(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3414; }
    { const char * tb_v3415 = "    return tb_gc_alloc_np(n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3415; }
    { const char * tb_v3416 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3416; }
    { const char * tb_v3417 = "// ---------- background: работа в своём потоке ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3417; }
    { const char * tb_v3418 = "#ifndef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3418; }
    { const char * tb_v3419 = "typedef struct { pthread_t th; int done; void *res; } tb_task;\n"; *(const char * *)tb_grow(v_lines) = tb_v3419; }
    { const char * tb_v3420 = "TB_API void tb_task_start(tb_task *t, void *(*run)(void *), void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3420; }
    { const char * tb_v3421 = "    t->done = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3421; }
    { const char * tb_v3422 = "    if (tb_thread_create(&t->th, run, arg) != 0) tb_crash(0, \"не получилось запустить background\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3422; }
    { const char * tb_v3423 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3423; }
    { const char * tb_v3424 = "// a.wait: дождаться потока (один раз) и отдать адрес ответа\n"; *(const char * *)tb_grow(v_lines) = tb_v3424; }
    { const char * tb_v3425 = "TB_API void *tb_wait(tb_task *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3425; }
    { const char * tb_v3426 = "    if (!t->done) { pthread_join(t->th, 0); t->done = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3426; }
    { const char * tb_v3427 = "    return t->res;\n"; *(const char * *)tb_grow(v_lines) = tb_v3427; }
    { const char * tb_v3428 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3428; }
    { const char * tb_v3429 = "// a.crashed: в обычной программе падение задачи роняет всю программу — сюда доходят только целые\n"; *(const char * *)tb_grow(v_lines) = tb_v3429; }
    { const char * tb_v3430 = "TB_API _Bool tb_crashed(tb_task *t) { tb_wait(t); return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3430; }
    { const char * tb_v3431 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3431; }
    { const char * tb_v3432 = "TB_API int tb_dhas(tb_dict *d, const void *k) { return tb_dfind(d, k) >= 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3432; }
    { const char * tb_v3433 = "TB_API void tb_dremove(tb_dict *d, const void *k) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3433; }
    { const char * tb_v3434 = "    long long at = tb_dfind(d, k);\n"; *(const char * *)tb_grow(v_lines) = tb_v3434; }
    { const char * tb_v3435 = "    if (at < 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3435; }
    { const char * tb_v3436 = "    if (d->mode != 0) tb_dto_hash(d);\n"; *(const char * *)tb_grow(v_lines) = tb_v3436; }
    { const char * tb_v3437 = "    long long last = d->keys->len - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3437; }
    { const char * tb_v3438 = "    // на место удалённого ставим последний: порядок меняется только у него\n"; *(const char * *)tb_grow(v_lines) = tb_v3438; }
    { const char * tb_v3439 = "    memcpy(d->keys->data + at * d->keys->size, d->keys->data + last * d->keys->size, d->keys->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3439; }
    { const char * tb_v3440 = "    memcpy(d->vals->data + at * d->vals->size, d->vals->data + last * d->vals->size, d->vals->size);\n"; *(const char * *)tb_grow(v_lines) = tb_v3440; }
    { const char * tb_v3441 = "    d->keys->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3441; }
    { const char * tb_v3442 = "    d->vals->len -= 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3442; }
    { const char * tb_v3443 = "    tb_dreindex(d, d->nslots);\n"; *(const char * *)tb_grow(v_lines) = tb_v3443; }
    { const char * tb_v3444 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3444; }
    { const char * tb_v3445 = "TB_API tb_dict *tb_dict_from(int text, long long vsize, long long n, const void *keys, const void *vals) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3445; }
    { const char * tb_v3446 = "    tb_dict *d = tb_dict_new(text, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3446; }
    { const char * tb_v3447 = "    long long ksize = d->keys->size;\n"; *(const char * *)tb_grow(v_lines) = tb_v3447; }
    { const char * tb_v3448 = "    for (long long i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3448; }
    { const char * tb_v3449 = "        memcpy(tb_dput(d, (const char *)keys + i * ksize, 0), (const char *)vals + i * vsize, vsize);\n"; *(const char * *)tb_grow(v_lines) = tb_v3449; }
    { const char * tb_v3450 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3450; }
