    { const char * tb_v3452 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3452; }
    { const char * tb_v3453 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3453; }
    { const char * tb_v3454 = "// ---------- on all cores: цикл на всех ядрах ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3454; }
    { const char * tb_v3455 = "// Работа делится на куски; каждое ядро берёт следующий свободный кусок,\n"; *(const char * *)tb_grow(v_lines) = tb_v3455; }
    { const char * tb_v3456 = "// пока они не кончатся (так ядра не простаивают, если куски разные по тяжести).\n"; *(const char * *)tb_grow(v_lines) = tb_v3456; }
    { const char * tb_v3457 = "// shared: каждое ядро копит своё на «листке», потом один раз добавляет под замком.\n"; *(const char * *)tb_grow(v_lines) = tb_v3457; }
    { const char * tb_v3458 = "TB_API pthread_mutex_t tb_par_lock = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3458; }
    { const char * tb_v3459 = "TB_API int tb_cores(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3459; }
    { const char * tb_v3460 = "    const char *want = getenv(\"TB_CORES\");   // TB_CORES=1 — проверить на одном ядре\n"; *(const char * *)tb_grow(v_lines) = tb_v3460; }
    { const char * tb_v3461 = "    long n = want != 0 ? atol(want) : sysconf(_SC_NPROCESSORS_ONLN);\n"; *(const char * *)tb_grow(v_lines) = tb_v3461; }
    { const char * tb_v3462 = "    return n < 1 ? 1 : (n > 256 ? 256 : (int)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3462; }
    { const char * tb_v3463 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3463; }
    { const char * tb_v3464 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3464; }
    { const char * tb_v3465 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3465; }
    { const char * tb_v3466 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3466; }
    { const char * tb_v3467 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3467; }
    { const char * tb_v3468 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3468; }
    { const char * tb_v3469 = "    pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3469; }
    { const char * tb_v3470 = "    for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3470; }
    { const char * tb_v3471 = "        if (pthread_create(&t[i], 0, work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3471; }
    { const char * tb_v3472 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3472; }
    { const char * tb_v3473 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3473; }
    { const char * tb_v3474 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3474; }
    { const char * tb_v3475 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3475; }
    { const char * tb_v3476 = "// Готовые потоки: создаются один раз (при первом on all cores) и ждут работу.\n"; *(const char * *)tb_grow(v_lines) = tb_v3476; }
    { const char * tb_v3477 = "// Раньше каждый цикл на ядрах создавал и закрывал потоки — для коротких циклов это было дольше самой работы.\n"; *(const char * *)tb_grow(v_lines) = tb_v3477; }
    { const char * tb_v3478 = "TB_API pthread_mutex_t tb_pool_m = PTHREAD_MUTEX_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3478; }
    { const char * tb_v3479 = "TB_API pthread_cond_t tb_pool_go = PTHREAD_COND_INITIALIZER, tb_pool_end = PTHREAD_COND_INITIALIZER;\n"; *(const char * *)tb_grow(v_lines) = tb_v3479; }
    { const char * tb_v3480 = "TB_API int tb_pool_n = 0, tb_pool_want = 0, tb_pool_busy = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3480; }
    { const char * tb_v3481 = "TB_API volatile long long tb_pool_gen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3481; }
    { const char * tb_v3482 = "TB_API volatile int tb_pool_left = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3482; }
    { const char * tb_v3483 = "TB_API void *(*tb_pool_work)(void *) = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3483; }
    { const char * tb_v3484 = "TB_API void *tb_pool_job = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3484; }
    { const char * tb_v3485 = "TB_API void *tb_pool_loop(void *arg) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3485; }
    { const char * tb_v3486 = "    int me = (int)(long long)arg;\n"; *(const char * *)tb_grow(v_lines) = tb_v3486; }
    { const char * tb_v3487 = "    // поток пула не считается «работающим», пока ждёт: уборка памяти может идти\n"; *(const char * *)tb_grow(v_lines) = tb_v3487; }
    { const char * tb_v3488 = "    __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3488; }
    { const char * tb_v3489 = "    long long seen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3489; }
    { const char * tb_v3490 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3490; }
    { const char * tb_v3491 = "        // немного ждём без сна: циклы на ядрах часто идут один за другим\n"; *(const char * *)tb_grow(v_lines) = tb_v3491; }
    { const char * tb_v3492 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_gen, __ATOMIC_ACQUIRE) == seen; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3492; }
    { const char * tb_v3493 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3493; }
    { const char * tb_v3494 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3494; }
    { const char * tb_v3495 = "        while (tb_pool_gen == seen) pthread_cond_wait(&tb_pool_go, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3495; }
    { const char * tb_v3496 = "        seen = tb_pool_gen;\n"; *(const char * *)tb_grow(v_lines) = tb_v3496; }
    { const char * tb_v3497 = "        int mine = me < tb_pool_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v3497; }
    { const char * tb_v3498 = "        void *(*work)(void *) = tb_pool_work;\n"; *(const char * *)tb_grow(v_lines) = tb_v3498; }
    { const char * tb_v3499 = "        void *job = tb_pool_job;\n"; *(const char * *)tb_grow(v_lines) = tb_v3499; }
    { const char * tb_v3500 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3500; }
    { const char * tb_v3501 = "        if (!mine) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v3501; }
    { const char * tb_v3502 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3502; }
    { const char * tb_v3503 = "        __atomic_sub_fetch(&tb_gthreads, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3503; }
    { const char * tb_v3504 = "        if (__atomic_sub_fetch(&tb_pool_left, 1, __ATOMIC_ACQ_REL) == 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3504; }
    { const char * tb_v3505 = "            pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3505; }
    { const char * tb_v3506 = "            pthread_cond_signal(&tb_pool_end);\n"; *(const char * *)tb_grow(v_lines) = tb_v3506; }
    { const char * tb_v3507 = "            pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3507; }
    { const char * tb_v3508 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3508; }
    { const char * tb_v3509 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3509; }
    { const char * tb_v3510 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3510; }
    { const char * tb_v3511 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3511; }
    { const char * tb_v3512 = "TB_API void tb_par_run(void *(*work)(void *), void *job, long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3512; }
    { const char * tb_v3513 = "    int n = tb_cores();\n"; *(const char * *)tb_grow(v_lines) = tb_v3513; }
    { const char * tb_v3514 = "    if (n > total) n = (int)total;\n"; *(const char * *)tb_grow(v_lines) = tb_v3514; }
    { const char * tb_v3515 = "    if (n < 1) n = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3515; }
    { const char * tb_v3516 = "    if (n == 1) { work(job); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3516; }
    { const char * tb_v3517 = "    // пул уже занят (цикл на ядрах из background или изнутри другого) — по-старому, своими потоками\n"; *(const char * *)tb_grow(v_lines) = tb_v3517; }
    { const char * tb_v3518 = "    if (__atomic_exchange_n(&tb_pool_busy, 1, __ATOMIC_ACQ_REL)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3518; }
    { const char * tb_v3519 = "        pthread_t t[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v3519; }
    { const char * tb_v3520 = "        for (int i = 1; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3520; }
    { const char * tb_v3521 = "            if (tb_thread_create(&t[i], work, job) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3521; }
    { const char * tb_v3522 = "        work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3522; }
    { const char * tb_v3523 = "        for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v3523; }
    { const char * tb_v3524 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3524; }
    { const char * tb_v3525 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3525; }
    { const char * tb_v3526 = "    while (tb_pool_n < n - 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3526; }
    { const char * tb_v3527 = "        pthread_t th;\n"; *(const char * *)tb_grow(v_lines) = tb_v3527; }
    { const char * tb_v3528 = "        if (tb_thread_create(&th, tb_pool_loop, (void *)(long long)tb_pool_n) != 0) tb_crash(0, \"не получилось запустить ядро\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3528; }
    { const char * tb_v3529 = "        pthread_detach(th);\n"; *(const char * *)tb_grow(v_lines) = tb_v3529; }
    { const char * tb_v3530 = "        tb_pool_n++;\n"; *(const char * *)tb_grow(v_lines) = tb_v3530; }
    { const char * tb_v3531 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3531; }
    { const char * tb_v3532 = "    pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3532; }
    { const char * tb_v3533 = "    tb_pool_work = work; tb_pool_job = job; tb_pool_want = n - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v3533; }
    { const char * tb_v3534 = "    __atomic_store_n(&tb_pool_left, n - 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3534; }
    { const char * tb_v3535 = "    __atomic_add_fetch(&tb_gthreads, n - 1, __ATOMIC_ACQ_REL);\n"; *(const char * *)tb_grow(v_lines) = tb_v3535; }
    { const char * tb_v3536 = "    __atomic_add_fetch(&tb_pool_gen, 1, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3536; }
    { const char * tb_v3537 = "    pthread_cond_broadcast(&tb_pool_go);\n"; *(const char * *)tb_grow(v_lines) = tb_v3537; }
    { const char * tb_v3538 = "    pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3538; }
    { const char * tb_v3539 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v3539; }
    { const char * tb_v3540 = "    if (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3540; }
    { const char * tb_v3541 = "        for (int spin = 0; spin < 20000 && __atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0; spin++)\n"; *(const char * *)tb_grow(v_lines) = tb_v3541; }
    { const char * tb_v3542 = "            __builtin_ia32_pause_or_yield();\n"; *(const char * *)tb_grow(v_lines) = tb_v3542; }
    { const char * tb_v3543 = "        pthread_mutex_lock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3543; }
    { const char * tb_v3544 = "        while (__atomic_load_n(&tb_pool_left, __ATOMIC_ACQUIRE) != 0) pthread_cond_wait(&tb_pool_end, &tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3544; }
    { const char * tb_v3545 = "        pthread_mutex_unlock(&tb_pool_m);\n"; *(const char * *)tb_grow(v_lines) = tb_v3545; }
    { const char * tb_v3546 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3546; }
    { const char * tb_v3547 = "    __atomic_store_n(&tb_pool_busy, 0, __ATOMIC_RELEASE);\n"; *(const char * *)tb_grow(v_lines) = tb_v3547; }
    { const char * tb_v3548 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3548; }
    { const char * tb_v3549 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3549; }
    { const char * tb_v3550 = "TB_API long long tb_par_step(long long total) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3550; }
    { const char * tb_v3551 = "    long long s = total / ((long long)tb_cores() * 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3551; }
    { const char * tb_v3552 = "    return s < 1 ? 1 : s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3552; }
    { const char * tb_v3553 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3553; }
    { const char * tb_v3554 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3554; }
    { const char * tb_v3555 = "// ---------- биты, адреса, порты, замки (danger и lock) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3555; }
    { const char * tb_v3556 = "TB_INL long long tb_band(long long a, long long b) { return a & b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3556; }
    { const char * tb_v3557 = "TB_INL long long tb_bor(long long a, long long b) { return a | b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3557; }
    { const char * tb_v3558 = "TB_INL long long tb_bxor(long long a, long long b) { return a ^ b; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3558; }
    { const char * tb_v3559 = "TB_INL long long tb_bnot(long long a) { return ~a; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3559; }
    { const char * tb_v3560 = "TB_INL long long tb_shl(long long a, long long n) { return (long long)((unsigned long long)a << (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3560; }
    { const char * tb_v3561 = "TB_INL long long tb_shr(long long a, long long n) { return (long long)((unsigned long long)a >> (n & 63)); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3561; }
    { const char * tb_v3562 = "// чтение и запись по адресу: volatile — компилятор C не выкинет и не переставит их\n"; *(const char * *)tb_grow(v_lines) = tb_v3562; }
    { const char * tb_v3563 = "// shared x += n без замка. В ядре без ОС одно ядро процессора: хватает выключить прерывания\n"; *(const char * *)tb_grow(v_lines) = tb_v3563; }
    { const char * tb_v3564 = "#ifdef TB_BARE\n"; *(const char * *)tb_grow(v_lines) = tb_v3564; }
    { const char * tb_v3565 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3565; }
    { const char * tb_v3566 = "static inline void tb_atomic_addd(volatile double *p, double v) { uint64_t f = tb_irq_save(); *p += v; tb_irq_restore(f); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3566; }
    { const char * tb_v3567 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3567; }
    { const char * tb_v3568 = "static inline void tb_atomic_addi(volatile long long *p, long long v) { __atomic_fetch_add(p, v, __ATOMIC_SEQ_CST); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3568; }
    { const char * tb_v3569 = "// дробь: сравнить и заменить, пока никто не успел поменять\n"; *(const char * *)tb_grow(v_lines) = tb_v3569; }
    { const char * tb_v3570 = "static inline void tb_atomic_addd(volatile double *p, double v) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3570; }
    { const char * tb_v3571 = "    volatile uint64_t *q = (volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3571; }
    { const char * tb_v3572 = "    uint64_t old = __atomic_load_n(q, __ATOMIC_SEQ_CST), nw;\n"; *(const char * *)tb_grow(v_lines) = tb_v3572; }
    { const char * tb_v3573 = "    do {\n"; *(const char * *)tb_grow(v_lines) = tb_v3573; }
