    { const char * tb_v3579 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3579; }
    { const char * tb_v3580 = "// ---------- память руками: new_mem, free_mem, grow_mem, copy_mem, fill_mem (только в danger) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3580; }
    { const char * tb_v3581 = "// Перед каждым блоком 16 байт: размер и метка «живой» / «освобождён» — так free_mem ловит чужой\n"; *(const char * *)tb_grow(v_lines) = tb_v3581; }
    { const char * tb_v3582 = "// адрес и второе освобождение. TB_MEM_CHECK=1 (не в ядре): за блоком 16 байт-сторожей, освобождённые\n"; *(const char * *)tb_grow(v_lines) = tb_v3582; }
    { const char * tb_v3583 = "// блоки не отдаются обратно (их чтение и запись ловятся), read/write/copy_mem/fill_mem проверяют\n"; *(const char * *)tb_grow(v_lines) = tb_v3583; }
    { const char * tb_v3584 = "// адрес, а в конце программы печатается, что не освобождено\n"; *(const char * *)tb_grow(v_lines) = tb_v3584; }
    { const char * tb_v3585 = "#define TB_MEM_LIVE 0x4D454D4C49564521ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3585; }
    { const char * tb_v3586 = "#define TB_MEM_DEAD 0x4D454D4445414421ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3586; }
    { const char * tb_v3587 = "#define TB_MEM_GUARD 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3587; }
    { const char * tb_v3588 = "typedef struct { uint64_t size, magic; } tb_memh;\n"; *(const char * *)tb_grow(v_lines) = tb_v3588; }
