    { const char * tb_v3736 = "    q->size = (uint64_t)n;\n"; *(const char * *)tb_grow(v_lines) = tb_v3736; }
    { const char * tb_v3737 = "    return (long long)(uintptr_t)(q + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3737; }
    { const char * tb_v3738 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3738; }
    { const char * tb_v3739 = "// copy_mem(куда, откуда, байт): блоки могут перекрываться\n"; *(const char * *)tb_grow(v_lines) = tb_v3739; }
    { const char * tb_v3740 = "TB_API void tb_copy_mem(long long dst, long long src, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3740; }
    { const char * tb_v3741 = "    if (n < 0) tb_crash(line, \"copy_mem: число байт меньше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3741; }
    { const char * tb_v3742 = "    if (n == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3742; }
    { const char * tb_v3743 = "    if (tb_memchk()) { tb_mem_touch((uintptr_t)src, (uint64_t)n, line); tb_mem_touch((uintptr_t)dst, (uint64_t)n, line); }\n"; *(const char * *)tb_grow(v_lines) = tb_v3743; }
    { const char * tb_v3744 = "    memmove((void *)(uintptr_t)dst, (const void *)(uintptr_t)src, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3744; }
    { const char * tb_v3745 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3745; }
    { const char * tb_v3746 = "// ---------- use c: функции из C ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3746; }
    { const char * tb_v3747 = "// настоящее имя функции C (на Mac у имён в библиотеке спереди _)\n"; *(const char * *)tb_grow(v_lines) = tb_v3747; }
    { const char * tb_v3748 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3748; }
    { const char * tb_v3749 = "#define TB_CSYM(s) __asm__(\"_\" s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3749; }
    { const char * tb_v3750 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3750; }
    { const char * tb_v3751 = "#define TB_CSYM(s) __asm__(s)\n"; *(const char * *)tb_grow(v_lines) = tb_v3751; }
    { const char * tb_v3752 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3752; }
    { const char * tb_v3753 = "// текст из C: копия в память Tachbit (C может потом поменять или отдать свой); NULL → \"\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3753; }
    { const char * tb_v3754 = "TB_API const char *tb_ctext(const char *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3754; }
    { const char * tb_v3755 = "    if (!p) return \"\";\n"; *(const char * *)tb_grow(v_lines) = tb_v3755; }
    { const char * tb_v3756 = "    size_t n = strlen(p);\n"; *(const char * *)tb_grow(v_lines) = tb_v3756; }
    { const char * tb_v3757 = "    char *s = tb_tmem(n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3757; }
    { const char * tb_v3758 = "    memcpy(s, p, n + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v3758; }
    { const char * tb_v3759 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3759; }
    { const char * tb_v3760 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3760; }
    { const char * tb_v3761 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3761; }
    { const char * tb_v3762 = "// ---------- zone: область памяти. Много кусков берутся быстро и освобождаются разом ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3762; }
    { const char * tb_v3763 = "// Зона — цепочка больших кусков. zone_take отрезает от текущего куска (16 байт выравнивание, нули),\n"; *(const char * *)tb_grow(v_lines) = tb_v3763; }
    { const char * tb_v3764 = "// кончился кусок — берёт новый. zone_clear отдаёт всё, кроме первого куска; zone_free — всё.\n"; *(const char * *)tb_grow(v_lines) = tb_v3764; }
    { const char * tb_v3765 = "#define TB_ZONE_LIVE 0x5A4F4E454C495645ULL\n"; *(const char * *)tb_grow(v_lines) = tb_v3765; }
    { const char * tb_v3766 = "typedef struct tb_zchunk { struct tb_zchunk *next; uint64_t size, used, pad; } tb_zchunk;   // 32 байта: данные с выравниванием 16\n"; *(const char * *)tb_grow(v_lines) = tb_v3766; }
    { const char * tb_v3767 = "typedef struct { uint64_t magic, step; tb_zchunk *first, *cur; } tb_zone;\n"; *(const char * *)tb_grow(v_lines) = tb_v3767; }
    { const char * tb_v3768 = "// данные куска: сразу за заголовком, с выравниванием 16 (malloc в ядре выравнивает меньше)\n"; *(const char * *)tb_grow(v_lines) = tb_v3768; }
    { const char * tb_v3769 = "#define TB_ZDATA(k) ((unsigned char *)(((uintptr_t)((k) + 1) + 15) & ~(uintptr_t)15))\n"; *(const char * *)tb_grow(v_lines) = tb_v3769; }
    { const char * tb_v3770 = "static tb_zchunk *tb_zone_chunk(uint64_t n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3770; }
    { const char * tb_v3771 = "    tb_zchunk *k = malloc(sizeof(tb_zchunk) + (size_t)n + 16);\n"; *(const char * *)tb_grow(v_lines) = tb_v3771; }
    { const char * tb_v3772 = "    if (!k) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3772; }
    { const char * tb_v3773 = "    k->next = 0; k->size = n; k->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3773; }
    { const char * tb_v3774 = "    memset(TB_ZDATA(k), 0, (size_t)n);\n"; *(const char * *)tb_grow(v_lines) = tb_v3774; }
    { const char * tb_v3775 = "    return k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3775; }
    { const char * tb_v3776 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3776; }
    { const char * tb_v3777 = "// zone_new(байт): первый кусок такого размера; дальше куски того же размера (или больше, если нужно)\n"; *(const char * *)tb_grow(v_lines) = tb_v3777; }
    { const char * tb_v3778 = "TB_API long long tb_zone_new(long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3778; }
    { const char * tb_v3779 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3779; }
    { const char * tb_v3780 = "    if (n <= 0) { tb_err = \"zone_new: размер должен быть больше нуля\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3780; }
    { const char * tb_v3781 = "    if ((unsigned long long)n > ((unsigned long long)1 << 46)) { tb_err = \"zone_new: слишком большой размер\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3781; }
    { const char * tb_v3782 = "    tb_zone *z = malloc(sizeof(tb_zone));\n"; *(const char * *)tb_grow(v_lines) = tb_v3782; }
    { const char * tb_v3783 = "    if (!z) { tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3783; }
    { const char * tb_v3784 = "    uint64_t step = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3784; }
    { const char * tb_v3785 = "    z->first = z->cur = tb_zone_chunk(step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3785; }
    { const char * tb_v3786 = "    if (!z->first) { free(z); tb_err = \"zone_new: не хватило памяти\"; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3786; }
    { const char * tb_v3787 = "    z->magic = TB_ZONE_LIVE; z->step = step;\n"; *(const char * *)tb_grow(v_lines) = tb_v3787; }
    { const char * tb_v3788 = "    return (long long)(uintptr_t)z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3788; }
    { const char * tb_v3789 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3789; }
    { const char * tb_v3790 = "static tb_zone *tb_zone_own(long long a, int line, const char *who) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3790; }
    { const char * tb_v3791 = "    tb_zone *z = (tb_zone *)(uintptr_t)a;\n"; *(const char * *)tb_grow(v_lines) = tb_v3791; }
    { const char * tb_v3792 = "    if (!z || z->magic != TB_ZONE_LIVE) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3792; }
    { const char * tb_v3793 = "        char buf[120];\n"; *(const char * *)tb_grow(v_lines) = tb_v3793; }
    { const char * tb_v3794 = "        snprintf(buf, sizeof buf, \"%s: это не зона из zone_new или она уже освобождена\", who);\n"; *(const char * *)tb_grow(v_lines) = tb_v3794; }
    { const char * tb_v3795 = "        tb_crash(line, buf);\n"; *(const char * *)tb_grow(v_lines) = tb_v3795; }
    { const char * tb_v3796 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3796; }
    { const char * tb_v3797 = "    return z;\n"; *(const char * *)tb_grow(v_lines) = tb_v3797; }
    { const char * tb_v3798 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3798; }
    { const char * tb_v3799 = "// zone_take(зона, байт): адрес нового куска (нули)\n"; *(const char * *)tb_grow(v_lines) = tb_v3799; }
    { const char * tb_v3800 = "TB_API long long tb_zone_take(long long a, long long n, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3800; }
    { const char * tb_v3801 = "    tb_zone *z = tb_zone_own(a, line, \"zone_take\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3801; }
    { const char * tb_v3802 = "    if (n <= 0) tb_crash(line, \"zone_take: размер должен быть больше нуля\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3802; }
    { const char * tb_v3803 = "    uint64_t need = ((uint64_t)n + 15) & ~(uint64_t)15;\n"; *(const char * *)tb_grow(v_lines) = tb_v3803; }
    { const char * tb_v3804 = "    tb_zchunk *k = z->cur;\n"; *(const char * *)tb_grow(v_lines) = tb_v3804; }
    { const char * tb_v3805 = "    if (k->size - k->used < need) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3805; }
    { const char * tb_v3806 = "        if (k->next && k->next->size >= need) k = k->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3806; }
    { const char * tb_v3807 = "        else {\n"; *(const char * *)tb_grow(v_lines) = tb_v3807; }
    { const char * tb_v3808 = "            tb_zchunk *nk = tb_zone_chunk(need > z->step ? need : z->step);\n"; *(const char * *)tb_grow(v_lines) = tb_v3808; }
    { const char * tb_v3809 = "            if (!nk) tb_crash(line, \"zone_take: не хватило памяти\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3809; }
    { const char * tb_v3810 = "            nk->next = k->next; k->next = nk; k = nk;\n"; *(const char * *)tb_grow(v_lines) = tb_v3810; }
    { const char * tb_v3811 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v3811; }
    { const char * tb_v3812 = "        z->cur = k;\n"; *(const char * *)tb_grow(v_lines) = tb_v3812; }
    { const char * tb_v3813 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v3813; }
    { const char * tb_v3814 = "    unsigned char *p = TB_ZDATA(k) + k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3814; }
    { const char * tb_v3815 = "    k->used += need;\n"; *(const char * *)tb_grow(v_lines) = tb_v3815; }
    { const char * tb_v3816 = "    return (long long)(uintptr_t)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3816; }
    { const char * tb_v3817 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3817; }
    { const char * tb_v3818 = "// zone_clear(зона): всё взятое больше не нужно; первый кусок остаётся для новых zone_take\n"; *(const char * *)tb_grow(v_lines) = tb_v3818; }
    { const char * tb_v3819 = "TB_API void tb_zone_clear(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3819; }
    { const char * tb_v3820 = "    tb_zone *z = tb_zone_own(a, line, \"zone_clear\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3820; }
    { const char * tb_v3821 = "    tb_zchunk *k = z->first->next;\n"; *(const char * *)tb_grow(v_lines) = tb_v3821; }
    { const char * tb_v3822 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3822; }
    { const char * tb_v3823 = "    z->first->next = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3823; }
    { const char * tb_v3824 = "    memset(TB_ZDATA(z->first), 0, (size_t)z->first->used);\n"; *(const char * *)tb_grow(v_lines) = tb_v3824; }
    { const char * tb_v3825 = "    z->first->used = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3825; }
    { const char * tb_v3826 = "    z->cur = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3826; }
    { const char * tb_v3827 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3827; }
    { const char * tb_v3828 = "// zone_free(зона): отдать всё; zone_free(0) ничего не делает\n"; *(const char * *)tb_grow(v_lines) = tb_v3828; }
    { const char * tb_v3829 = "TB_API void tb_zone_free(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3829; }
    { const char * tb_v3830 = "    if (a == 0) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v3830; }
    { const char * tb_v3831 = "    tb_zone *z = tb_zone_own(a, line, \"zone_free\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3831; }
    { const char * tb_v3832 = "    tb_zchunk *k = z->first;\n"; *(const char * *)tb_grow(v_lines) = tb_v3832; }
    { const char * tb_v3833 = "    while (k) { tb_zchunk *nx = k->next; free(k); k = nx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v3833; }
    { const char * tb_v3834 = "    z->magic = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3834; }
    { const char * tb_v3835 = "    free(z);\n"; *(const char * *)tb_grow(v_lines) = tb_v3835; }
    { const char * tb_v3836 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3836; }
    { const char * tb_v3837 = "// zone_used(зона): сколько байт взято (с выравниванием)\n"; *(const char * *)tb_grow(v_lines) = tb_v3837; }
    { const char * tb_v3838 = "TB_API long long tb_zone_used(long long a, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3838; }
    { const char * tb_v3839 = "    tb_zone *z = tb_zone_own(a, line, \"zone_used\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3839; }
    { const char * tb_v3840 = "    long long s = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3840; }
    { const char * tb_v3841 = "    for (tb_zchunk *k = z->first; k; k = k->next) s += (long long)k->used;\n"; *(const char * *)tb_grow(v_lines) = tb_v3841; }
    { const char * tb_v3842 = "    return s;\n"; *(const char * *)tb_grow(v_lines) = tb_v3842; }
    { const char * tb_v3843 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3843; }
    { const char * tb_v3844 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3844; }
    { const char * tb_v3845 = "// ---------- syscall(номер, ...): прямой вызов ядра ОС (Linux, Mac). Ответ -1 → -номер ошибки ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3845; }
    { const char * tb_v3846 = "#if !defined(TB_BARE) && !defined(_WIN32)\n"; *(const char * *)tb_grow(v_lines) = tb_v3846; }
    { const char * tb_v3847 = "#include <sys/syscall.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3847; }
    { const char * tb_v3848 = "#include <errno.h>\n"; *(const char * *)tb_grow(v_lines) = tb_v3848; }
    { const char * tb_v3849 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3849; }
    { const char * tb_v3850 = "#pragma clang diagnostic push\n"; *(const char * *)tb_grow(v_lines) = tb_v3850; }
    { const char * tb_v3851 = "#pragma clang diagnostic ignored \"-Wdeprecated-declarations\"\n"; *(const char * *)tb_grow(v_lines) = tb_v3851; }
    { const char * tb_v3852 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3852; }
    { const char * tb_v3853 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3853; }
    { const char * tb_v3854 = "    (void)line;\n"; *(const char * *)tb_grow(v_lines) = tb_v3854; }
    { const char * tb_v3855 = "    long r = syscall((long)n, (long)a, (long)b, (long)c, (long)d, (long)e, (long)f);\n"; *(const char * *)tb_grow(v_lines) = tb_v3855; }
    { const char * tb_v3856 = "    if (r == -1) return -(long long)errno;\n"; *(const char * *)tb_grow(v_lines) = tb_v3856; }
    { const char * tb_v3857 = "    return (long long)r;\n"; *(const char * *)tb_grow(v_lines) = tb_v3857; }
    { const char * tb_v3858 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3858; }
    { const char * tb_v3859 = "#ifdef __APPLE__\n"; *(const char * *)tb_grow(v_lines) = tb_v3859; }
    { const char * tb_v3860 = "#pragma clang diagnostic pop\n"; *(const char * *)tb_grow(v_lines) = tb_v3860; }
    { const char * tb_v3861 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3861; }
    { const char * tb_v3862 = "#else\n"; *(const char * *)tb_grow(v_lines) = tb_v3862; }
    { const char * tb_v3863 = "TB_API long long tb_syscall(long long n, long long a, long long b, long long c, long long d, long long e, long long f, int line) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3863; }
    { const char * tb_v3864 = "    (void)n; (void)a; (void)b; (void)c; (void)d; (void)e; (void)f;\n"; *(const char * *)tb_grow(v_lines) = tb_v3864; }
    { const char * tb_v3865 = "    tb_crash(line, \"syscall есть только на Linux и Mac\");\n"; *(const char * *)tb_grow(v_lines) = tb_v3865; }
    { const char * tb_v3866 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v3866; }
    { const char * tb_v3867 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v3867; }
    { const char * tb_v3868 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v3868; }
    { const char * tb_v3869 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v3869; }
    { const char * tb_v3870 = "// ---------- shape: поля с размером прямо в памяти (регистры, заголовки пакетов) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v3870; }
    { const char * tb_v3871 = "// k = смещение × 2^20 + байт (1, 2, 4, 8; 0 — bytes: отдать адрес) + 16 со знаком + 32 big\n"; *(const char * *)tb_grow(v_lines) = tb_v3871; }
    { const char * tb_v3872 = "//     + 64 × первый бит + 4096 × сколько бит (0 — поле целиком).\n"; *(const char * *)tb_grow(v_lines) = tb_v3872; }
    { const char * tb_v3873 = "// Поле читается и пишется одним volatile-доступом своей ширины: регистр u32 — одной 32-битной операцией.\n"; *(const char * *)tb_grow(v_lines) = tb_v3873; }
    { const char * tb_v3874 = "static inline uint64_t tb_shape_raw(uintptr_t p, int nb) {\n"; *(const char * *)tb_grow(v_lines) = tb_v3874; }
    { const char * tb_v3875 = "    if (nb == 1) return *(volatile uint8_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3875; }
    { const char * tb_v3876 = "    if (nb == 2) return *(volatile uint16_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3876; }
    { const char * tb_v3877 = "    if (nb == 4) return *(volatile uint32_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3877; }
    { const char * tb_v3878 = "    return *(volatile uint64_t *)p;\n"; *(const char * *)tb_grow(v_lines) = tb_v3878; }
