    { const char * tb_v4249 = "// короткий щелчок (касание тачпада): нажали и отпустили между двумя кадрами — mouse_down() всё равно разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v4249; }
    { const char * tb_v4250 = "TB_API int tb_mtap = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4250; }
    { const char * tb_v4251 = "// колёсико: шагов с прошлого mouse_wheel() (+ вперёд, от себя; − назад); у тачпада шаги дробные — копим\n"; *(const char * *)tb_grow(v_lines) = tb_v4251; }
    { const char * tb_v4252 = "TB_API int tb_wheel = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4252; }
    { const char * tb_v4253 = "// боковые кнопки мыши: [0] назад, [1] вперёд; tap — нажали и отпустили между кадрами\n"; *(const char * *)tb_grow(v_lines) = tb_v4253; }
    { const char * tb_v4254 = "TB_API int tb_mside[2], tb_mside_tap[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v4254; }
    { const char * tb_v4255 = "TB_API void tb_side(int b, int down) { tb_mside[b] = down; if (down) tb_mside_tap[b] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4255; }
    { const char * tb_v4256 = "TB_API double tb_wheel_f = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4256; }
    { const char * tb_v4257 = "TB_API void tb_wheel_add(double d) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4257; }
    { const char * tb_v4258 = "    tb_wheel_f += d;\n"; *(const char * *)tb_grow(v_lines) = tb_v4258; }
    { const char * tb_v4259 = "    int n = (int)tb_wheel_f;\n"; *(const char * *)tb_grow(v_lines) = tb_v4259; }
    { const char * tb_v4260 = "    tb_wheel += n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4260; }
    { const char * tb_v4261 = "    tb_wheel_f -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4261; }
    { const char * tb_v4262 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4262; }
    { const char * tb_v4263 = "// буквы, набранные с прошлого typed_text(), в UTF-8 (стрелки, Enter и прочие не буквы не попадают)\n"; *(const char * *)tb_grow(v_lines) = tb_v4263; }
    { const char * tb_v4264 = "TB_API char tb_typed[512];\n"; *(const char * *)tb_grow(v_lines) = tb_v4264; }
    { const char * tb_v4265 = "TB_API int tb_ntyped = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4265; }
    { const char * tb_v4266 = "TB_API char *tb_gfx_clip_get(void);          // свои у каждой системы: текст (malloc) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v4266; }
    { const char * tb_v4267 = "TB_API void tb_gfx_clip_set(const char *s);\n"; *(const char * *)tb_grow(v_lines) = tb_v4267; }
    { const char * tb_v4268 = "TB_API void tb_gfx_cursor(int k);              // 0 стрелка, 1 рука, 2 текст, 3 двигать, 4 ↔, 5 ↕, 6 ждать, 7 спрятать\n"; *(const char * *)tb_grow(v_lines) = tb_v4268; }
    { const char * tb_v4269 = "TB_API int tb_cursor_want = 0;                 // курсор, который просили до window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v4269; }
    { const char * tb_v4270 = "TB_API void tb_type_cp(unsigned u) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4270; }
    { const char * tb_v4271 = "    if (u < 32 || u == 127 || (u >= 0xF700 && u <= 0xF8FF) || u > 0x10FFFF) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4271; }
    { const char * tb_v4272 = "    if (tb_ntyped + 4 >= (int)sizeof tb_typed) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4272; }
    { const char * tb_v4273 = "    char *o = tb_typed + tb_ntyped;\n"; *(const char * *)tb_grow(v_lines) = tb_v4273; }
    { const char * tb_v4274 = "    if (u < 0x80) { o[0] = (char)u; tb_ntyped += 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4274; }
    { const char * tb_v4275 = "    else if (u < 0x800) { o[0] = (char)(0xC0 | (u >> 6)); o[1] = (char)(0x80 | (u & 63)); tb_ntyped += 2; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4275; }
    { const char * tb_v4276 = "    else if (u < 0x10000) { o[0] = (char)(0xE0 | (u >> 12)); o[1] = (char)(0x80 | ((u >> 6) & 63)); o[2] = (char)(0x80 | (u & 63)); tb_ntyped += 3; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4276; }
    { const char * tb_v4277 = "    else { o[0] = (char)(0xF0 | (u >> 18)); o[1] = (char)(0x80 | ((u >> 12) & 63)); o[2] = (char)(0x80 | ((u >> 6) & 63)); o[3] = (char)(0x80 | (u & 63)); tb_ntyped += 4; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4277; }
    { const char * tb_v4278 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4278; }
    { const char * tb_v4279 = "TB_API void tb_type_utf8(const char *s) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4279; }
    { const char * tb_v4280 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4280; }
    { const char * tb_v4281 = "    while (p && *p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4281; }
    { const char * tb_v4282 = "        unsigned u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4282; }
    { const char * tb_v4283 = "        if (u >= 0x80) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4283; }
    { const char * tb_v4284 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4284; }
    { const char * tb_v4285 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v4285; }
    { const char * tb_v4286 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v4286; }
    { const char * tb_v4287 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v4287; }
    { const char * tb_v4288 = "        tb_type_cp(u);\n"; *(const char * *)tb_grow(v_lines) = tb_v4288; }
    { const char * tb_v4289 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4289; }
    { const char * tb_v4290 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4290; }
    { const char * tb_v4291 = "TB_API unsigned char tb_keys[256];\n"; *(const char * *)tb_grow(v_lines) = tb_v4291; }
    { const char * tb_v4292 = "TB_API unsigned char tb_ktap[256];   // клавишу нажали и отпустили между кадрами: key_down() разок скажет «да»\n"; *(const char * *)tb_grow(v_lines) = tb_v4292; }
    { const char * tb_v4293 = "TB_API long long tb_last_frame = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4293; }
    { const char * tb_v4294 = "// клавиши: буквы и цифры — свой код ASCII (A..Z, 0..9), остальные:\n"; *(const char * *)tb_grow(v_lines) = tb_v4294; }
    { const char * tb_v4295 = "enum { TB_K_ENTER = 10, TB_K_ESC = 27, TB_K_SPACE = 32, TB_K_BACK = 8, TB_K_TAB = 9,\n"; *(const char * *)tb_grow(v_lines) = tb_v4295; }
    { const char * tb_v4296 = "       TB_K_UP = 17, TB_K_DOWN = 18, TB_K_RIGHT = 19, TB_K_LEFT = 20, TB_K_SHIFT = 21,\n"; *(const char * *)tb_grow(v_lines) = tb_v4296; }
    { const char * tb_v4297 = "       TB_K_CMD = 1, TB_K_CTRL = 2, TB_K_ALT = 3, TB_K_DEL = 4, TB_K_HOME = 5, TB_K_END = 6, TB_K_PGUP = 7,\n"; *(const char * *)tb_grow(v_lines) = tb_v4297; }
    { const char * tb_v4298 = "       TB_K_PGDN = 11, TB_K_F1 = 128 };   // F1..F12 — 128..139\n"; *(const char * *)tb_grow(v_lines) = tb_v4298; }
    { const char * tb_v4299 = "// ---------- картинки PNG (load_image) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4299; }
    { const char * tb_v4300 = "// Свой маленький разбор PNG: распаковка deflate (как zlib) и фильтры строк.\n"; *(const char * *)tb_grow(v_lines) = tb_v4300; }
    { const char * tb_v4301 = "// Картинка хранится точками 0xAARRGGBB; точка видна, если её прозрачность (A) не меньше 128.\n"; *(const char * *)tb_grow(v_lines) = tb_v4301; }
    { const char * tb_v4302 = "typedef struct { const unsigned char *p, *end; unsigned bits; int nb, err; unsigned char *out; size_t n, cap; } tb_zs;\n"; *(const char * *)tb_grow(v_lines) = tb_v4302; }
    { const char * tb_v4303 = "typedef struct { short count[16], sym[320]; } tb_huff;\n"; *(const char * *)tb_grow(v_lines) = tb_v4303; }
    { const char * tb_v4304 = "TB_API unsigned tb_zbits(tb_zs *z, int n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4304; }
    { const char * tb_v4305 = "    while (z->nb < n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4305; }
    { const char * tb_v4306 = "        if (z->p >= z->end) { z->err = 1; return 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4306; }
    { const char * tb_v4307 = "        z->bits |= (unsigned)*z->p++ << z->nb; z->nb += 8;\n"; *(const char * *)tb_grow(v_lines) = tb_v4307; }
    { const char * tb_v4308 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4308; }
    { const char * tb_v4309 = "    unsigned v = z->bits & ((1u << n) - 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v4309; }
    { const char * tb_v4310 = "    z->bits >>= n; z->nb -= n;\n"; *(const char * *)tb_grow(v_lines) = tb_v4310; }
    { const char * tb_v4311 = "    return v;\n"; *(const char * *)tb_grow(v_lines) = tb_v4311; }
    { const char * tb_v4312 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4312; }
