    { const char * tb_v4540 = "// ---------- шрифты TTF: свой чтец (таблицы glyf, без чужих библиотек) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4540; }
    { const char * tb_v4541 = "// Буква рисуется на процессоре один раз в маленькую картинку с прозрачностью (сглаживание),\n"; *(const char * *)tb_grow(v_lines) = tb_v4541; }
    { const char * tb_v4542 = "// дальше её рисуют и видеокарта, и процессор одинаково: точка = (цвет * a + фон * (255 - a)) / 255.\n"; *(const char * *)tb_grow(v_lines) = tb_v4542; }
    { const char * tb_v4543 = "typedef struct { unsigned char *d; size_t n; uint32_t glyf, loca, hmtx, cmap; int upem, locfmt, nglyphs, nhm, asc, desc, cfmt; } tb_font_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4543; }
    { const char * tb_v4544 = "TB_API tb_font_t *tb_fonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4544; }
    { const char * tb_v4545 = "TB_API int tb_nfonts = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4545; }
    { const char * tb_v4546 = "static unsigned tb_u16(const tb_font_t *f, size_t o) { return o + 2 <= f->n ? (unsigned)(f->d[o] << 8 | f->d[o + 1]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4546; }
    { const char * tb_v4547 = "static int tb_s16(const tb_font_t *f, size_t o) { return (int16_t)tb_u16(f, o); }\n"; *(const char * *)tb_grow(v_lines) = tb_v4547; }
    { const char * tb_v4548 = "static uint32_t tb_u32(const tb_font_t *f, size_t o) { return o + 4 <= f->n ? ((uint32_t)f->d[o] << 24 | (uint32_t)f->d[o + 1] << 16 | (uint32_t)f->d[o + 2] << 8 | f->d[o + 3]) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4548; }
    { const char * tb_v4549 = "static uint32_t tb_ttf_table(const tb_font_t *f, size_t base, const char *tag) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4549; }
    { const char * tb_v4550 = "    unsigned n = tb_u16(f, base + 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v4550; }
    { const char * tb_v4551 = "    for (unsigned i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4551; }
    { const char * tb_v4552 = "        size_t e = base + 12 + 16 * (size_t)i;\n"; *(const char * *)tb_grow(v_lines) = tb_v4552; }
    { const char * tb_v4553 = "        if (e + 16 <= f->n && memcmp(f->d + e, tag, 4) == 0) return tb_u32(f, e + 8);\n"; *(const char * *)tb_grow(v_lines) = tb_v4553; }
    { const char * tb_v4554 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4554; }
    { const char * tb_v4555 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4555; }
    { const char * tb_v4556 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4556; }
    { const char * tb_v4557 = "TB_API void tb_gpu_blend_probe(void);   // TB_GPU_CHECK: проба смешивания букв (ниже)\n"; *(const char * *)tb_grow(v_lines) = tb_v4557; }
    { const char * tb_v4558 = "TB_API long long tb_load_font(const char *path) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4558; }
    { const char * tb_v4559 = "    FILE *fp = fopen(path, \"rb\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4559; }
    { const char * tb_v4560 = "    if (!fp) { tb_err = tb_cat(\"нет такого файла шрифта: \", path); return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4560; }
    { const char * tb_v4561 = "    fseek(fp, 0, SEEK_END); long sz = ftell(fp); fseek(fp, 0, SEEK_SET);\n"; *(const char * *)tb_grow(v_lines) = tb_v4561; }
    { const char * tb_v4562 = "    unsigned char *d = sz > 12 ? malloc((size_t)sz) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4562; }
    { const char * tb_v4563 = "    if (!d || fread(d, 1, (size_t)sz, fp) != (size_t)sz) { fclose(fp); free(d); tb_err = \"не могу прочитать файл шрифта\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4563; }
    { const char * tb_v4564 = "    fclose(fp);\n"; *(const char * *)tb_grow(v_lines) = tb_v4564; }
    { const char * tb_v4565 = "    tb_font_t f = { d, (size_t)sz };\n"; *(const char * *)tb_grow(v_lines) = tb_v4565; }
    { const char * tb_v4566 = "    size_t base = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4566; }
    { const char * tb_v4567 = "    if (memcmp(d, \"ttcf\", 4) == 0) base = tb_u32(&f, 12);   // сборник шрифтов (.ttc): берём первый\n"; *(const char * *)tb_grow(v_lines) = tb_v4567; }
    { const char * tb_v4568 = "    uint32_t head = tb_ttf_table(&f, base, \"head\"), maxp = tb_ttf_table(&f, base, \"maxp\"), hhea = tb_ttf_table(&f, base, \"hhea\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4568; }
    { const char * tb_v4569 = "    f.glyf = tb_ttf_table(&f, base, \"glyf\"); f.loca = tb_ttf_table(&f, base, \"loca\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4569; }
    { const char * tb_v4570 = "    f.hmtx = tb_ttf_table(&f, base, \"hmtx\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4570; }
    { const char * tb_v4571 = "    uint32_t cmap = tb_ttf_table(&f, base, \"cmap\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4571; }
    { const char * tb_v4572 = "    if (!f.glyf || !f.loca) { free(d); tb_err = \"этот шрифт не TrueType (контуры CFF/OTF пока не читаю): возьми .ttf\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4572; }
    { const char * tb_v4573 = "    if (!head || !maxp || !hhea || !f.hmtx || !cmap) { free(d); tb_err = \"шрифт сломан: нет нужных таблиц\"; return -1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4573; }
