    { const char * tb_v4863 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4863; }
    { const char * tb_v4864 = "TB_API long long tb_text_width(long long fi, const char *s, long long size) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4864; }
    { const char * tb_v4865 = "    if (fi < 0 || fi >= tb_nfonts || size <= 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4865; }
    { const char * tb_v4866 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v4866; }
    { const char * tb_v4867 = "    double scale = (double)size / f->upem, pen = 0, best = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4867; }
    { const char * tb_v4868 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4868; }
    { const char * tb_v4869 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4869; }
    { const char * tb_v4870 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4870; }
