    { const char * tb_v4873 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4873; }
    { const char * tb_v4874 = "    if (pen > best) best = pen;\n"; *(const char * *)tb_grow(v_lines) = tb_v4874; }
    { const char * tb_v4875 = "    return (long long)floor(best + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4875; }
    { const char * tb_v4876 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4876; }
    { const char * tb_v4877 = "TB_API void tb_draw_image_a(long long id, long long x, long long y);\n"; *(const char * *)tb_grow(v_lines) = tb_v4877; }
    { const char * tb_v4878 = "TB_API void tb_draw_font(long long fi, long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4878; }
    { const char * tb_v4879 = "    if (!tb_px || fi < 0 || fi >= tb_nfonts || size <= 0 || size > 1000) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4879; }
    { const char * tb_v4880 = "    const tb_font_t *f = &tb_fonts[fi];\n"; *(const char * *)tb_grow(v_lines) = tb_v4880; }
    { const char * tb_v4881 = "    double scale = (double)size / f->upem, pen = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4881; }
    { const char * tb_v4882 = "    long long base = y + tb_font_base(f, size), lh = size * 5 / 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v4882; }
    { const char * tb_v4883 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v4883; }
    { const char * tb_v4884 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4884; }
    { const char * tb_v4885 = "        unsigned u = tb_utf8_next(&p);\n"; *(const char * *)tb_grow(v_lines) = tb_v4885; }
    { const char * tb_v4886 = "        if (u == '\\n') { pen = 0; base += lh; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4886; }
    { const char * tb_v4887 = "        unsigned g = tb_ttf_glyph(f, u);\n"; *(const char * *)tb_grow(v_lines) = tb_v4887; }
    { const char * tb_v4888 = "        long long gx = x + (long long)floor(pen + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v4888; }
    { const char * tb_v4889 = "        pen += tb_ttf_adv(f, g) * scale;\n"; *(const char * *)tb_grow(v_lines) = tb_v4889; }
    { const char * tb_v4890 = "        if (u == ' ' || gx >= tb_gw || base - 2 * size > tb_gh) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v4890; }
    { const char * tb_v4891 = "        tb_gcache *gc = tb_glyph_img((int)fi, g, (int)size, (uint32_t)c & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4891; }
    { const char * tb_v4892 = "        if (gc->img >= 0) tb_draw_image_a(gc->img, gx + gc->left, base + gc->top);\n"; *(const char * *)tb_grow(v_lines) = tb_v4892; }
    { const char * tb_v4893 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4893; }
    { const char * tb_v4894 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4894; }
    { const char * tb_v4895 = "// ---------- рисование на видеокарте (GPU) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v4895; }
    { const char * tb_v4896 = "// Кадр не рисуется точками на процессоре: каждая фигура записывается как «экземпляр»\n"; *(const char * *)tb_grow(v_lines) = tb_v4896; }
    { const char * tb_v4897 = "// (прямоугольник, круг или буква), а видеокарта рисует их все разом — по тем же правилам\n"; *(const char * *)tb_grow(v_lines) = tb_v4897; }
    { const char * tb_v4898 = "// точек, что и процессор (tb_draw_* ниже). Mac — Metal, Linux и Windows — Vulkan.\n"; *(const char * *)tb_grow(v_lines) = tb_v4898; }
    { const char * tb_v4899 = "// Если видеокарты нет (нет драйвера Vulkan, нет экрана) — рисуем как раньше, на процессоре.\n"; *(const char * *)tb_grow(v_lines) = tb_v4899; }
    { const char * tb_v4900 = "//   TB_GPU=0        — всегда на процессоре\n"; *(const char * *)tb_grow(v_lines) = tb_v4900; }
    { const char * tb_v4901 = "//   TB_GPU_CHECK=1  — рисовать и там и там и сверять каждый кадр точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4901; }
    { const char * tb_v4902 = "//   TB_GPU_INFO=1   — сказать, чем рисуем\n"; *(const char * *)tb_grow(v_lines) = tb_v4902; }
    { const char * tb_v4903 = "typedef struct { int32_t x0, y0, x1, y1, ox, oy; uint32_t c, m; } tb_ginst;   // 32 байта\n"; *(const char * *)tb_grow(v_lines) = tb_v4903; }
    { const char * tb_v4904 = "enum { TB_GI_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4904; }
    { const char * tb_v4905 = "TB_API int tb_gpu_on = 0, tb_gpu_check = 0, tb_gpu_first = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4905; }
    { const char * tb_v4906 = "TB_API tb_ginst *tb_gi = 0;            // память экземпляров (видна видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4906; }
    { const char * tb_v4907 = "TB_API int tb_gin = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4907; }
    { const char * tb_v4908 = "// 3D: глубина. У треугольника сетки своя «плоскость глубины» A, B, C (целые числа, см. tb_tri3_depth);\n"; *(const char * *)tb_grow(v_lines) = tb_v4908; }
    { const char * tb_v4909 = "// она лежит в tb_gplane[набор * TB_GI_CAP + номер фигуры], а в m — 2 | (это место << 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4909; }
    { const char * tb_v4910 = "typedef struct { uint32_t a, b, c, pad; } tb_gplane_t;\n"; *(const char * *)tb_grow(v_lines) = tb_v4910; }
    { const char * tb_v4911 = "TB_API tb_gplane_t *tb_gplane = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4911; }
    { const char * tb_v4912 = "TB_API int tb_gzclr = 1;               // видеокарта: в начале кадра стереть глубину\n"; *(const char * *)tb_grow(v_lines) = tb_v4912; }
    { const char * tb_v4913 = "TB_API int tb_zclr = 1;                // процессор: то же для tb_zb\n"; *(const char * *)tb_grow(v_lines) = tb_v4913; }
    { const char * tb_v4914 = "TB_API uint32_t *tb_zb = 0;            // процессор: глубина каждой точки\n"; *(const char * *)tb_grow(v_lines) = tb_v4914; }
    { const char * tb_v4915 = "TB_API long long tb_zb_n = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4915; }
    { const char * tb_v4916 = "// 3D на видеокарте: сетка один раз ложится в память видеокарты (tb_mesh_pack), а на каждый draw_mesh\n"; *(const char * *)tb_grow(v_lines) = tb_v4916; }
    { const char * tb_v4917 = "// пишется только запись: 3 строки по 4 целых — поворот (камера × поворот сетки) × 2^30 и сдвиг × 4096.\n"; *(const char * *)tb_grow(v_lines) = tb_v4917; }
    { const char * tb_v4918 = "// В пачке фигур это одна особая фигура m = 3: x0 — сетка, y0 — какие грани не видны, x1 — первая запись,\n"; *(const char * *)tb_grow(v_lines) = tb_v4918; }
    { const char * tb_v4919 = "// y1 — сколько записей подряд. Углы, экран и глубину считает видеокарта (tb3.vert) целыми числами —\n"; *(const char * *)tb_grow(v_lines) = tb_v4919; }
    { const char * tb_v4920 = "// той же формулой, что процессор (tb_m3_corner): кадры совпадают точка в точку\n"; *(const char * *)tb_grow(v_lines) = tb_v4920; }
    { const char * tb_v4921 = "typedef struct { int32_t r[12]; } tb_grec;\n"; *(const char * *)tb_grow(v_lines) = tb_v4921; }
    { const char * tb_v4922 = "enum { TB_GR_CAP = 65536 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4922; }
    { const char * tb_v4923 = "TB_API tb_grec *tb_grec_p = 0;         // записи всех наборов подряд (видны видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4923; }
    { const char * tb_v4924 = "TB_API int tb_grn = 0;                 // сколько записей в текущем наборе\n"; *(const char * *)tb_grow(v_lines) = tb_v4924; }
    { const char * tb_v4925 = "TB_API int tb_gpu_mesh = 0;            // 1: видеокарта умеет считать сетки сама (конвейер собрался)\n"; *(const char * *)tb_grow(v_lines) = tb_v4925; }
    { const char * tb_v4926 = "TB_API int tb_mesh_gdirty = 1;         // сетки поменялись: перед рисованием залить заново\n"; *(const char * *)tb_grow(v_lines) = tb_v4926; }
    { const char * tb_v4927 = "TB_API long long tb_gbatch = 1;        // номер текущей пачки (растёт после каждой отдачи видеокарте)\n"; *(const char * *)tb_grow(v_lines) = tb_v4927; }
    { const char * tb_v4928 = "typedef struct { float size[2]; int32_t tbase, ntri, rbase, f, gw, gh, cull; } tb_gpc;   // постоянные шейдера сеток\n"; *(const char * *)tb_grow(v_lines) = tb_v4928; }
    { const char * tb_v4929 = "TB_API long long tb_mesh_pack(int32_t *dst);   // все сетки подряд для видеокарты (dst = 0: только размер)\n"; *(const char * *)tb_grow(v_lines) = tb_v4929; }
    { const char * tb_v4930 = "TB_API void tb_mesh_gpc(const tb_ginst *g, int slot, tb_gpc *pc);   // постоянные для фигуры m = 3\n"; *(const char * *)tb_grow(v_lines) = tb_v4930; }
    { const char * tb_v4931 = "// TB_GSLOTS наборов памяти по кругу: пока видеокарта рисует один кадр, программа уже пишет следующий\n"; *(const char * *)tb_grow(v_lines) = tb_v4931; }
    { const char * tb_v4932 = "enum { TB_GSLOTS = 3 };\n"; *(const char * *)tb_grow(v_lines) = tb_v4932; }
    { const char * tb_v4933 = "TB_API int tb_gslot = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4933; }
    { const char * tb_v4934 = "TB_API uint32_t *tb_gpu_back = 0;      // TB_GPU_CHECK: кадр, прочитанный обратно с видеокарты\n"; *(const char * *)tb_grow(v_lines) = tb_v4934; }
    { const char * tb_v4935 = "TB_API long long tb_gpu_frames = 0, tb_gpu_bad = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4935; }
    { const char * tb_v4936 = "TB_API void tb_gpu_flush(int present);   // своя у каждой системы: Metal или Vulkan\n"; *(const char * *)tb_grow(v_lines) = tb_v4936; }
    { const char * tb_v4937 = "TB_API void tb_gpu_vsync(void);          // включить или выключить ожидание экрана (tb_gpu_nosync)\n"; *(const char * *)tb_grow(v_lines) = tb_v4937; }
    { const char * tb_v4938 = "TB_API int tb_gpu_nosync = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4938; }
    { const char * tb_v4939 = "TB_API int tb_gpu_resize(int ow, int oh);   // окно поменяло размер\n"; *(const char * *)tb_grow(v_lines) = tb_v4939; }
    { const char * tb_v4940 = "// окно можно тянуть мышью, если программа спросила его размер (window_w, window_h)\n"; *(const char * *)tb_grow(v_lines) = tb_v4940; }
    { const char * tb_v4941 = "TB_API int tb_resizable = 0, tb_new_w = 0, tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4941; }
    { const char * tb_v4942 = "TB_API int tb_sharp = 0;       // window_sharp(): окно в настоящих точках экрана\n"; *(const char * *)tb_grow(v_lines) = tb_v4942; }
    { const char * tb_v4943 = "TB_API double tb_sc = 1;        // во сколько раз точек больше (Retina — 2)\n"; *(const char * *)tb_grow(v_lines) = tb_v4943; }
    { const char * tb_v4944 = "TB_API void tb_gfx_resizable(void);   // свои у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v4944; }
    { const char * tb_v4945 = "TB_API void tb_gfx_reimage(void);            // 1: не ждать обновления экрана (set_fps(0), TB_FPS_FREE=1)\n"; *(const char * *)tb_grow(v_lines) = tb_v4945; }
    { const char * tb_v4946 = "TB_API int tb_gpu_want(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4946; }
    { const char * tb_v4947 = "    const char *e = getenv(\"TB_GPU\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4947; }
    { const char * tb_v4948 = "    tb_gpu_check = getenv(\"TB_GPU_CHECK\") != 0 && getenv(\"TB_GPU_CHECK\")[0] == '1';\n"; *(const char * *)tb_grow(v_lines) = tb_v4948; }
    { const char * tb_v4949 = "    if (getenv(\"TB_FPS_FREE\")) tb_gpu_nosync = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4949; }
    { const char * tb_v4950 = "    return !(e && e[0] == '0');\n"; *(const char * *)tb_grow(v_lines) = tb_v4950; }
    { const char * tb_v4951 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4951; }
    { const char * tb_v4952 = "TB_API void tb_gpu_say(const char *what) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4952; }
    { const char * tb_v4953 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v4953; }
    { const char * tb_v4954 = "    if ((e && e[0] == '1') || tb_gpu_check) fprintf(stderr, \"окно: рисует %s\\n\", what);\n"; *(const char * *)tb_grow(v_lines) = tb_v4954; }
    { const char * tb_v4955 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4955; }
    { const char * tb_v4956 = "TB_API void tb_gpu_report(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4956; }
    { const char * tb_v4957 = "    fprintf(stderr, \"TB_GPU_CHECK: кадров %lld, разошлось %lld\\n\", tb_gpu_frames, tb_gpu_bad);\n"; *(const char * *)tb_grow(v_lines) = tb_v4957; }
    { const char * tb_v4958 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4958; }
    { const char * tb_v4959 = "// сверить кадр видеокарты с кадром процессора (видны только младшие 24 бита цвета)\n"; *(const char * *)tb_grow(v_lines) = tb_v4959; }
    { const char * tb_v4960 = "// TB_GPU_CHECK: как видеокарта смешивает букву с фоном — таблица из пробы (tb_gpu_blend_probe)\n"; *(const char * *)tb_grow(v_lines) = tb_v4960; }
    { const char * tb_v4961 = "TB_API int tb_blend_cal = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v4961; }
    { const char * tb_v4962 = "TB_API uint8_t *tb_blend_lut = 0;   // [цвет][фон][a] → точка, 2^24 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v4962; }
    { const char * tb_v4963 = "TB_API int tb_gpu_probing = 0;   // TB_GPU_CHECK: идёт проба смешивания (tb_gpu_blend_probe), кадры не сверять\n"; *(const char * *)tb_grow(v_lines) = tb_v4963; }
    { const char * tb_v4964 = "TB_API void tb_gpu_compare(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4964; }
    { const char * tb_v4965 = "    if (!tb_gpu_back || tb_gpu_probing) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4965; }
    { const char * tb_v4966 = "    tb_gpu_frames++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4966; }
    { const char * tb_v4967 = "    long long n = (long long)tb_gw * tb_gh, bad = 0, first = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4967; }
    { const char * tb_v4968 = "    for (long long i = 0; i < n; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v4968; }
    { const char * tb_v4969 = "        if (((tb_gpu_back[i] ^ tb_px[i]) & 0xFFFFFF) != 0) { if (first < 0) first = i; bad++; }\n"; *(const char * *)tb_grow(v_lines) = tb_v4969; }
    { const char * tb_v4970 = "    if (bad) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4970; }
    { const char * tb_v4971 = "        tb_gpu_bad++;\n"; *(const char * *)tb_grow(v_lines) = tb_v4971; }
    { const char * tb_v4972 = "        if (tb_gpu_bad <= 5)\n"; *(const char * *)tb_grow(v_lines) = tb_v4972; }
    { const char * tb_v4973 = "            fprintf(stderr, \"TB_GPU_CHECK: кадр %lld: не совпало точек %lld, первая x=%lld y=%lld: видеокарта %06x, процессор %06x\\n\",\n"; *(const char * *)tb_grow(v_lines) = tb_v4973; }
    { const char * tb_v4974 = "                tb_gpu_frames, bad, first % tb_gw, first / tb_gw, tb_gpu_back[first] & 0xFFFFFF, tb_px[first] & 0xFFFFFF);\n"; *(const char * *)tb_grow(v_lines) = tb_v4974; }
    { const char * tb_v4975 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v4975; }
    { const char * tb_v4976 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4976; }
    { const char * tb_v4977 = "TB_INL void tb_gpu_add(long long x0, long long y0, long long x1, long long y1, long long ox, long long oy, uint32_t c, uint32_t m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4977; }
    { const char * tb_v4978 = "    if (tb_gin == TB_GI_CAP) tb_gpu_flush(0);\n"; *(const char * *)tb_grow(v_lines) = tb_v4978; }
    { const char * tb_v4979 = "    tb_ginst *g = &tb_gi[tb_gin++];\n"; *(const char * *)tb_grow(v_lines) = tb_v4979; }
    { const char * tb_v4980 = "    g->x0 = (int32_t)x0; g->y0 = (int32_t)y0; g->x1 = (int32_t)x1; g->y1 = (int32_t)y1;\n"; *(const char * *)tb_grow(v_lines) = tb_v4980; }
    { const char * tb_v4981 = "    g->ox = (int32_t)ox; g->oy = (int32_t)oy; g->c = c; g->m = m;\n"; *(const char * *)tb_grow(v_lines) = tb_v4981; }
    { const char * tb_v4982 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v4982; }
    { const char * tb_v4983 = "// прямоугольник: обрезан окном; соседние полоски одного цвета склеиваются (линии, точки по одной)\n"; *(const char * *)tb_grow(v_lines) = tb_v4983; }
    { const char * tb_v4984 = "TB_API void tb_gpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4984; }
    { const char * tb_v4985 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v4985; }
    { const char * tb_v4986 = "    if (x0 >= x1 || y0 >= y1) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v4986; }
    { const char * tb_v4987 = "    uint32_t cc = (uint32_t)c & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v4987; }
    { const char * tb_v4988 = "    if (tb_gin > 0) {\n"; *(const char * *)tb_grow(v_lines) = tb_v4988; }
