    { const char * tb_v6549 = "// Экран и мышь Омниума (tb bare + рисование): видеокарта QEMU/Bochs, мышь PS/2 и vmmouse.\n"; *(const char * *)tb_grow(v_lines) = tb_v6549; }
    { const char * tb_v6550 = "// Вставляется в compiler/runtime.h на место строки //@include (tools/embed_runtime.py).\n"; *(const char * *)tb_grow(v_lines) = tb_v6550; }
