    { const char * tb_v6552 = "// ---------- экран и мышь в ядре (tb bare) ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v6552; }
    { const char * tb_v6553 = "// Экран: видеокарта Bochs/QEMU (BGA, «-vga std»): режим w×h, 32 бита на точку, буфер кадра в памяти.\n"; *(const char * *)tb_grow(v_lines) = tb_v6553; }
