    { const char * tb_v6558 = "TB_API char *tb_bclip = 0;       // буфер обмена — просто текст в памяти ядра\n"; *(const char * *)tb_grow(v_lines) = tb_v6558; }
    { const char * tb_v6559 = "TB_API unsigned tb_pci_r(int bus, int dev, int fn, int off) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6559; }
