    { const char * tb_v6566 = "            unsigned id = tb_pci_r(bus, dev, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v6566; }
    { const char * tb_v6567 = "            if (id == 0x11111234u || id == 0xBEEF80EEu) return tb_pci_r(bus, dev, 0, 0x10) & ~0xFu;\n"; *(const char * *)tb_grow(v_lines) = tb_v6567; }
    { const char * tb_v6568 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v6568; }
