    { const char * tb_v6581 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6581; }
    { const char * tb_v6582 = "// --- клавиши для key_down / typed_text (набор 1, как шлёт контроллер клавиатуры) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v6582; }
    { const char * tb_v6583 = "TB_API int tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6583; }
