    { const char * tb_v6589 = "        case 0x49: return TB_K_PGUP; case 0x51: return TB_K_PGDN; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6589; }
    { const char * tb_v6590 = "        case 0x1C: return TB_K_ENTER;\n"; *(const char * *)tb_grow(v_lines) = tb_v6590; }
