    { const char * tb_v6593 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6593; }
    { const char * tb_v6594 = "    switch (sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6594; }
    { const char * tb_v6595 = "    case 0x1C: return TB_K_ENTER; case 0x01: return TB_K_ESC; case 0x39: return TB_K_SPACE; case 0x0E: return TB_K_BACK;\n"; *(const char * *)tb_grow(v_lines) = tb_v6595; }
    { const char * tb_v6596 = "    case 0x0F: return TB_K_TAB; case 0x2A: case 0x36: return TB_K_SHIFT; case 0x1D: return TB_K_CTRL; case 0x38: return TB_K_ALT;\n"; *(const char * *)tb_grow(v_lines) = tb_v6596; }
    { const char * tb_v6597 = "    case 0x57: return TB_K_F1 + 10; case 0x58: return TB_K_F1 + 11;\n"; *(const char * *)tb_grow(v_lines) = tb_v6597; }
    { const char * tb_v6598 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6598; }
