    { const char * tb_v6604 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v6604; }
    { const char * tb_v6605 = "    return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6605; }
    { const char * tb_v6606 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6606; }
    { const char * tb_v6607 = "TB_API void tb_gfx_key(unsigned char sc) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6607; }
    { const char * tb_v6608 = "    if (sc == 0xE0) { tb_kext = 1; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6608; }
    { const char * tb_v6609 = "    int up = sc & 0x80, ext = tb_kext;\n"; *(const char * *)tb_grow(v_lines) = tb_v6609; }
    { const char * tb_v6610 = "    tb_kext = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6610; }
