    { const char * tb_v6612 = "    int k = tb_sc_key(sc, ext);\n"; *(const char * *)tb_grow(v_lines) = tb_v6612; }
    { const char * tb_v6613 = "    if (k) { tb_keys[k] = !up; if (!up) tb_ktap[k] = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v6613; }
    { const char * tb_v6614 = "    if (!up && !ext && sc < 58 && !tb_keys[TB_K_CTRL]) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6614; }
