    { const char * tb_v6618 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6618; }
    { const char * tb_v6619 = "// --- мышь PS/2: пакеты по 3 байта (по 4 — с колёсиком) ---\n"; *(const char * *)tb_grow(v_lines) = tb_v6619; }
    { const char * tb_v6620 = "TB_API unsigned char tb_mpk[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v6620; }
    { const char * tb_v6621 = "TB_API int tb_mpn = 0, tb_mpsize = 3;\n"; *(const char * *)tb_grow(v_lines) = tb_v6621; }
    { const char * tb_v6622 = "TB_API void tb_ps2_wait_in(void) { for (int i = 0; i < 100000 && (tb_inb(0x64) & 2); i++) {} }\n"; *(const char * *)tb_grow(v_lines) = tb_v6622; }
    { const char * tb_v6623 = "TB_API int tb_ps2_read(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6623; }
    { const char * tb_v6624 = "    for (int i = 0; i < 100000; i++) if (tb_inb(0x64) & 1) return tb_inb(0x60);\n"; *(const char * *)tb_grow(v_lines) = tb_v6624; }
    { const char * tb_v6625 = "    return -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v6625; }
    { const char * tb_v6626 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6626; }
    { const char * tb_v6627 = "TB_API int tb_mouse_cmd(unsigned char c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v6627; }
    { const char * tb_v6628 = "    tb_ps2_wait_in(); tb_outb(0x64, 0xD4);\n"; *(const char * *)tb_grow(v_lines) = tb_v6628; }
