    { const char * tb_v6631 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v6631; }
    { const char * tb_v6632 = "// «мышь виртуальной машины» (vmmouse в QEMU и VMware): точное место курсора, а не сдвиги —\n"; *(const char * *)tb_grow(v_lines) = tb_v6632; }
    { const char * tb_v6633 = "// мышь не надо «ловить» в окне QEMU. Есть — берём её, нет — обычные пакеты PS/2\n"; *(const char * *)tb_grow(v_lines) = tb_v6633; }
    { const char * tb_v6634 = "TB_API int tb_vmm = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v6634; }
