    { const char * tb_v6641 = "    uint32_t r[4];\n"; *(const char * *)tb_grow(v_lines) = tb_v6641; }
    { const char * tb_v6642 = "    tb_vmm_call(10, 0, r);                               // «кто здесь»: в ответе ebx — тот же магический номер\n"; *(const char * *)tb_grow(v_lines) = tb_v6642; }
