    { const char * tb_v7714 = "            tb_new_w = e.xconfigure.width; tb_new_h = e.xconfigure.height;\n"; *(const char * *)tb_grow(v_lines) = tb_v7714; }
    { const char * tb_v7715 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7715; }
    { const char * tb_v7716 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7716; }
    { const char * tb_v7717 = "    XFlush(tb_dpy);\n"; *(const char * *)tb_grow(v_lines) = tb_v7717; }
    { const char * tb_v7718 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7718; }
    { const char * tb_v7719 = "#endif\n"; *(const char * *)tb_grow(v_lines) = tb_v7719; }
    { const char * tb_v7720 = "// TB_GPU_CHECK: проба смешивания. Видеокарты считают смешивание по-своему (AMD на Mac — с малой\n"; *(const char * *)tb_grow(v_lines) = tb_v7720; }
    { const char * tb_v7721 = "// точностью, ошибка зависит и от цвета буквы, и от фона), поэтому проба берёт все сочетания:\n"; *(const char * *)tb_grow(v_lines) = tb_v7721; }
    { const char * tb_v7722 = "// цвет c, фон d, прозрачность a — 256 × 256 × 256 точек, кадр за кадром, и процессор дальше\n"; *(const char * *)tb_grow(v_lines) = tb_v7722; }
    { const char * tb_v7723 = "// смешивает по этой таблице (tb_blend_lut[c][d][a]). Делается один раз, когда есть и окно, и шрифт.\n"; *(const char * *)tb_grow(v_lines) = tb_v7723; }
    { const char * tb_v7724 = "// После пробы кадр видеокарты снова становится таким же, как у процессора (копия tb_px)\n"; *(const char * *)tb_grow(v_lines) = tb_v7724; }
    { const char * tb_v7725 = "TB_API void tb_gpu_blend_probe(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7725; }
    { const char * tb_v7726 = "    if (!tb_gpu_on || !tb_gpu_check || tb_blend_cal || !tb_px || !tb_nfonts) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7726; }
    { const char * tb_v7727 = "    uint8_t *lut = malloc((size_t)1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7727; }
    { const char * tb_v7728 = "    if (!lut) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7728; }
    { const char * tb_v7729 = "    size_t n = (size_t)tb_gw * tb_gh, p0 = tb_imgpx_n, need = p0 + 3 * n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7729; }
    { const char * tb_v7730 = "    int n0 = tb_nimg;\n"; *(const char * *)tb_grow(v_lines) = tb_v7730; }
    { const char * tb_v7731 = "    uint32_t *all = need <= 0xFFFFFFFFu ? realloc(tb_imgpx, need * 4) : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7731; }
    { const char * tb_v7732 = "    tb_image *list = realloc(tb_imgs, (size_t)(n0 + 3) * sizeof(tb_image));\n"; *(const char * *)tb_grow(v_lines) = tb_v7732; }
    { const char * tb_v7733 = "    if (all) tb_imgpx = all;\n"; *(const char * *)tb_grow(v_lines) = tb_v7733; }
    { const char * tb_v7734 = "    if (list) tb_imgs = list;\n"; *(const char * *)tb_grow(v_lines) = tb_v7734; }
    { const char * tb_v7735 = "    if (!all || !list) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7735; }
    { const char * tb_v7736 = "    for (int k = 0; k < 3; k++) { tb_imgs[n0 + k].w = tb_gw; tb_imgs[n0 + k].h = tb_gh; tb_imgs[n0 + k].off = (uint32_t)(p0 + k * n); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7736; }
    { const char * tb_v7737 = "    tb_nimg = n0 + 3; tb_imgpx_n = need;\n"; *(const char * *)tb_grow(v_lines) = tb_v7737; }
    { const char * tb_v7738 = "    uint32_t *keep = tb_imgpx + p0 + 2 * n;   // кадр процессора: вернуть его видеокарте после пробы\n"; *(const char * *)tb_grow(v_lines) = tb_v7738; }
    { const char * tb_v7739 = "    for (size_t q = 0; q < n; q++) keep[q] = 0xFF000000u | tb_px[q];\n"; *(const char * *)tb_grow(v_lines) = tb_v7739; }
    { const char * tb_v7740 = "    tb_gpu_probing = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7740; }
    { const char * tb_v7741 = "    int ok = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7741; }
    { const char * tb_v7742 = "    for (size_t from = 0; from < ((size_t)1 << 24) && ok; from += n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7742; }
    { const char * tb_v7743 = "        uint32_t *bg = tb_imgpx + p0, *fg = bg + n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7743; }
    { const char * tb_v7744 = "        for (size_t q = 0; q < n; q++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7744; }
    { const char * tb_v7745 = "            size_t i = (from + q) & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v7745; }
    { const char * tb_v7746 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7746; }
    { const char * tb_v7747 = "            bg[q] = 0xFF000000u | d * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v7747; }
    { const char * tb_v7748 = "            fg[q] = (a << 24) | c * 0x010101u;\n"; *(const char * *)tb_grow(v_lines) = tb_v7748; }
    { const char * tb_v7749 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7749; }
    { const char * tb_v7750 = "        tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7750; }
    { const char * tb_v7751 = "        tb_gpu_image(n0, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7751; }
    { const char * tb_v7752 = "        tb_gpu_image_a(n0 + 1, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7752; }
    { const char * tb_v7753 = "        tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7753; }
    { const char * tb_v7754 = "        if (!tb_gpu_back) { ok = 0; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7754; }
    { const char * tb_v7755 = "        for (size_t q = 0; q < n && from + q < ((size_t)1 << 24); q++) lut[from + q] = (uint8_t)(tb_gpu_back[q] & 255);\n"; *(const char * *)tb_grow(v_lines) = tb_v7755; }
    { const char * tb_v7756 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7756; }
    { const char * tb_v7757 = "    tb_gpu_image(n0 + 2, 0, 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v7757; }
    { const char * tb_v7758 = "    tb_gpu_flush(1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7758; }
    { const char * tb_v7759 = "    tb_gpu_probing = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7759; }
    { const char * tb_v7760 = "    tb_nimg = n0; tb_imgpx_n = p0; tb_img_dirty = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7760; }
    { const char * tb_v7761 = "    if (!ok) { free(lut); return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7761; }
    { const char * tb_v7762 = "    tb_blend_lut = lut;\n"; *(const char * *)tb_grow(v_lines) = tb_v7762; }
    { const char * tb_v7763 = "    tb_blend_cal = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7763; }
    { const char * tb_v7764 = "    const char *e = getenv(\"TB_GPU_INFO\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7764; }
    { const char * tb_v7765 = "    if (e && e[0] == '1') {\n"; *(const char * *)tb_grow(v_lines) = tb_v7765; }
    { const char * tb_v7766 = "        long long diff = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7766; }
    { const char * tb_v7767 = "        for (size_t i = 0; i < ((size_t)1 << 24); i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7767; }
    { const char * tb_v7768 = "            uint32_t c = (uint32_t)(i >> 16), d = (uint32_t)(i >> 8) & 255, a = (uint32_t)i & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7768; }
    { const char * tb_v7769 = "            uint32_t w = a == 0 ? d : (c * a + 127) / 255 + (d * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v7769; }
    { const char * tb_v7770 = "            diff += lut[i] != w;\n"; *(const char * *)tb_grow(v_lines) = tb_v7770; }
    { const char * tb_v7771 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7771; }
    { const char * tb_v7772 = "        fprintf(stderr, \"TB_GPU_CHECK: смешивание на этой видеокарте не как округление к ближайшему: %lld из %d\\n\", diff, 1 << 24);\n"; *(const char * *)tb_grow(v_lines) = tb_v7772; }
    { const char * tb_v7773 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7773; }
    { const char * tb_v7774 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7774; }
    { const char * tb_v7775 = "// window_sharp(): окно в настоящих точках экрана (Retina, 150% и 200% на Windows). Размер в window_open\n"; *(const char * *)tb_grow(v_lines) = tb_v7775; }
    { const char * tb_v7776 = "// остаётся в «обычных» точках, а кадр, window_w/h и мышь — в настоящих; window_scale() — во сколько раз\n"; *(const char * *)tb_grow(v_lines) = tb_v7776; }
    { const char * tb_v7777 = "TB_API double tb_gfx_scale(void);   // своя у каждой системы\n"; *(const char * *)tb_grow(v_lines) = tb_v7777; }
    { const char * tb_v7778 = "TB_API void tb_window_sharp(void) { if (!tb_px) tb_sharp = 1; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7778; }
    { const char * tb_v7779 = "TB_API double tb_window_scale(void) { return tb_sc; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7779; }
    { const char * tb_v7780 = "TB_API void tb_window_open(long long w, long long h, const char *title) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7780; }
    { const char * tb_v7781 = "    if (tb_px) { tb_err = \"окно уже открыто\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7781; }
    { const char * tb_v7782 = "    if (w < 1 || h < 1 || w > 8192 || h > 8192) { tb_err = \"размер окна от 1 до 8192\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7782; }
    { const char * tb_v7783 = "    if (tb_sharp) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7783; }
    { const char * tb_v7784 = "        tb_sc = tb_gfx_scale();\n"; *(const char * *)tb_grow(v_lines) = tb_v7784; }
    { const char * tb_v7785 = "        if (tb_sc < 1) tb_sc = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7785; }
    { const char * tb_v7786 = "        if (tb_sc > 4) tb_sc = 4;\n"; *(const char * *)tb_grow(v_lines) = tb_v7786; }
    { const char * tb_v7787 = "        w = (long long)(w * tb_sc + 0.5); h = (long long)(h * tb_sc + 0.5);\n"; *(const char * *)tb_grow(v_lines) = tb_v7787; }
    { const char * tb_v7788 = "        if (w > 8192) w = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7788; }
    { const char * tb_v7789 = "        if (h > 8192) h = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7789; }
    { const char * tb_v7790 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7790; }
    { const char * tb_v7791 = "    tb_gw = (int)w; tb_gh = (int)h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7791; }
    { const char * tb_v7792 = "    tb_px = calloc((size_t)tb_gw * tb_gh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7792; }
    { const char * tb_v7793 = "    if (!tb_gfx_open(title)) { free(tb_px); tb_px = 0; tb_err = \"не могу открыть окно: нет экрана\"; return; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7793; }
    { const char * tb_v7794 = "    if (tb_gpu_on && tb_gpu_check) { atexit(tb_gpu_report); tb_gpu_blend_probe(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7794; }
    { const char * tb_v7795 = "    tb_last_frame = tb_time_ms();\n"; *(const char * *)tb_grow(v_lines) = tb_v7795; }
    { const char * tb_v7796 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7796; }
    { const char * tb_v7797 = "// показать кадр, принять клавиши и мышь, держать 60 кадров в секунду; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v7797; }
    { const char * tb_v7798 = "// окно поменяло размер: новый кадр, старое остаётся в левом верхнем углу, новое место — чёрное\n"; *(const char * *)tb_grow(v_lines) = tb_v7798; }
    { const char * tb_v7799 = "TB_API void tb_apply_resize(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7799; }
    { const char * tb_v7800 = "    if (!tb_new_w) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7800; }
    { const char * tb_v7801 = "    int nw = tb_new_w > 8192 ? 8192 : tb_new_w, nh = tb_new_h > 8192 ? 8192 : tb_new_h, ow = tb_gw, oh = tb_gh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7801; }
    { const char * tb_v7802 = "    tb_new_w = tb_new_h = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7802; }
    { const char * tb_v7803 = "    if (nw < 1 || nh < 1 || (nw == ow && nh == oh)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7803; }
    { const char * tb_v7804 = "    uint32_t *np = calloc((size_t)nw * nh, 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7804; }
    { const char * tb_v7805 = "    if (!np) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7805; }
    { const char * tb_v7806 = "    for (int y = 0; y < oh && y < nh; y++) memcpy(np + (size_t)y * nw, tb_px + (size_t)y * ow, (size_t)(ow < nw ? ow : nw) * 4);\n"; *(const char * *)tb_grow(v_lines) = tb_v7806; }
    { const char * tb_v7807 = "    free(tb_px);\n"; *(const char * *)tb_grow(v_lines) = tb_v7807; }
    { const char * tb_v7808 = "    tb_px = np; tb_gw = nw; tb_gh = nh;\n"; *(const char * *)tb_grow(v_lines) = tb_v7808; }
    { const char * tb_v7809 = "    tb_gfx_reimage();\n"; *(const char * *)tb_grow(v_lines) = tb_v7809; }
    { const char * tb_v7810 = "    if (tb_gpu_on && !tb_gpu_resize(ow, oh)) fprintf(stderr, \"видеокарта: не получилось поменять размер кадра\\n\");\n"; *(const char * *)tb_grow(v_lines) = tb_v7810; }
    { const char * tb_v7811 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7811; }
    { const char * tb_v7812 = "TB_API long long tb_window_w(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gw; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7812; }
    { const char * tb_v7813 = "TB_API long long tb_window_h(void) { if (tb_px && !tb_resizable) { tb_resizable = 1; tb_gfx_resizable(); } return tb_gh; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7813; }
    { const char * tb_v7814 = "// частота кадров: -1 — как у экрана (по умолчанию), 0 — сколько успеет, n — n кадров в секунду (set_fps)\n"; *(const char * *)tb_grow(v_lines) = tb_v7814; }
    { const char * tb_v7815 = "TB_API double tb_frame_ms_v = 16.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7815; }
    { const char * tb_v7816 = "TB_API long long tb_fps_want = -1, tb_fps_v = 0, tb_fps_n = 0, tb_fps_t0 = 0, tb_last_us = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7816; }
    { const char * tb_v7817 = "TB_API void tb_set_fps(long long n) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7817; }
    { const char * tb_v7818 = "    if (n < 0) n = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7818; }
    { const char * tb_v7819 = "    tb_fps_want = n;\n"; *(const char * *)tb_grow(v_lines) = tb_v7819; }
    { const char * tb_v7820 = "    int nosync = n == 0 || getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7820; }
    { const char * tb_v7821 = "    if (nosync != tb_gpu_nosync) { tb_gpu_nosync = nosync; if (tb_gpu_on) tb_gpu_vsync(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7821; }
    { const char * tb_v7822 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7822; }
    { const char * tb_v7823 = "TB_API double tb_frame_ms(void) { return tb_frame_ms_v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7823; }
    { const char * tb_v7824 = "TB_API long long tb_fps(void) { return tb_fps_v ? tb_fps_v : tb_frame_ms_v > 0 ? (long long)(1000 / tb_frame_ms_v) : 0; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7824; }
    { const char * tb_v7825 = "// показать кадр, принять клавиши и мышь, держать частоту кадров; false — окно закрыли\n"; *(const char * *)tb_grow(v_lines) = tb_v7825; }
    { const char * tb_v7826 = "TB_API int tb_window_alive(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7826; }
    { const char * tb_v7827 = "    if (!tb_px || tb_gclosed) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7827; }
    { const char * tb_v7828 = "    tb_gfx_events();   // здесь показывается прошлый кадр\n"; *(const char * *)tb_grow(v_lines) = tb_v7828; }
    { const char * tb_v7829 = "    tb_zclr = tb_gzclr = 1;   // новый кадр: глубина 3D начинается заново\n"; *(const char * *)tb_grow(v_lines) = tb_v7829; }
    { const char * tb_v7830 = "    tb_apply_resize();\n"; *(const char * *)tb_grow(v_lines) = tb_v7830; }
    { const char * tb_v7831 = "    // TB_FPS_FREE=1 — без ограничения (для замеров скорости), как set_fps(0)\n"; *(const char * *)tb_grow(v_lines) = tb_v7831; }
    { const char * tb_v7832 = "    static int free_fps = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7832; }
    { const char * tb_v7833 = "    if (free_fps < 0) free_fps = getenv(\"TB_FPS_FREE\") != 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7833; }
    { const char * tb_v7834 = "    long long now = tb_time_us(), period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7834; }
    { const char * tb_v7835 = "    if (!tb_last_us) tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v7835; }
    { const char * tb_v7836 = "    if (free_fps || tb_fps_want == 0) period = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7836; }
    { const char * tb_v7837 = "    else if (tb_fps_want > 0) period = 1000000 / tb_fps_want;\n"; *(const char * *)tb_grow(v_lines) = tb_v7837; }
    { const char * tb_v7838 = "    // как у экрана: видеокарта сама ждёт обновления экрана (60 Гц — 60 кадров, 120 Гц — 120);\n"; *(const char * *)tb_grow(v_lines) = tb_v7838; }
    { const char * tb_v7839 = "    // кадр пришёл быстрее 4 мс — экран частоту не держит, держим сами 60 кадров в секунду\n"; *(const char * *)tb_grow(v_lines) = tb_v7839; }
    { const char * tb_v7840 = "    else if (!tb_gpu_on || now - tb_last_us < 4000) period = 16667;\n"; *(const char * *)tb_grow(v_lines) = tb_v7840; }
    { const char * tb_v7841 = "    if (period && now - tb_last_us < period) { usleep((useconds_t)(period - (now - tb_last_us))); now = tb_time_us(); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7841; }
    { const char * tb_v7842 = "    tb_frame_ms_v = (now - tb_last_us) / 1000.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7842; }
    { const char * tb_v7843 = "    tb_last_us = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v7843; }
    { const char * tb_v7844 = "    if (!tb_fps_t0) tb_fps_t0 = now;\n"; *(const char * *)tb_grow(v_lines) = tb_v7844; }
