    { const char * tb_v7849 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7849; }
    { const char * tb_v7850 = "TB_INL void tb_put(long long x, long long y, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7850; }
    { const char * tb_v7851 = "    if (tb_px && x >= 0 && y >= 0 && x < tb_gw && y < tb_gh) tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7851; }
    { const char * tb_v7852 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7852; }
    { const char * tb_v7853 = "// на видеокарте фигуры записываются (tb_gpu_*), на процессоре — рисуются сразу в tb_px.\n"; *(const char * *)tb_grow(v_lines) = tb_v7853; }
    { const char * tb_v7854 = "// TB_GPU_CHECK=1: и то и другое, кадры сверяются\n"; *(const char * *)tb_grow(v_lines) = tb_v7854; }
    { const char * tb_v7855 = "#define TB_CPU_DRAW (!tb_gpu_on || tb_gpu_check)\n"; *(const char * *)tb_grow(v_lines) = tb_v7855; }
    { const char * tb_v7856 = "TB_API void tb_clear_window(long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7856; }
    { const char * tb_v7857 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7857; }
    { const char * tb_v7858 = "    if (tb_gpu_on) { tb_gin = 0; tb_gpu_rect(0, 0, tb_gw, tb_gh, c); }   // всё прежнее закрашено\n"; *(const char * *)tb_grow(v_lines) = tb_v7858; }
    { const char * tb_v7859 = "    if (TB_CPU_DRAW) for (long long i = 0; i < (long long)tb_gw * tb_gh; i++) tb_px[i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7859; }
    { const char * tb_v7860 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7860; }
