    { const char * tb_v7866 = "// полупрозрачный цвет (rgba): в старшем байте — прозрачность 1..255 (0 — непрозрачный, как у rgb)\n"; *(const char * *)tb_grow(v_lines) = tb_v7866; }
    { const char * tb_v7867 = "TB_INL uint32_t tb_mix(uint32_t d, uint32_t c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7867; }
    { const char * tb_v7868 = "    uint32_t t = (c >> 24) & 255, a = 255 - t;\n"; *(const char * *)tb_grow(v_lines) = tb_v7868; }
    { const char * tb_v7869 = "    uint32_t rb = ((c & 0xFF00FF) * a + (d & 0xFF00FF) * t + 0x800080) >> 8 & 0xFF00FF;\n"; *(const char * *)tb_grow(v_lines) = tb_v7869; }
    { const char * tb_v7870 = "    uint32_t g = ((c & 0x00FF00) * a + (d & 0x00FF00) * t + 0x008000) >> 8 & 0x00FF00;\n"; *(const char * *)tb_grow(v_lines) = tb_v7870; }
    { const char * tb_v7871 = "    return rb | g;\n"; *(const char * *)tb_grow(v_lines) = tb_v7871; }
    { const char * tb_v7872 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7872; }
    { const char * tb_v7873 = "TB_API void tb_cpu_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7873; }
    { const char * tb_v7874 = "    long long x0 = x < 0 ? 0 : x, y0 = y < 0 ? 0 : y, x1 = x + w > tb_gw ? tb_gw : x + w, y1 = y + h > tb_gh ? tb_gh : y + h;\n"; *(const char * *)tb_grow(v_lines) = tb_v7874; }
    { const char * tb_v7875 = "    if ((c >> 24) & 255) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7875; }
    { const char * tb_v7876 = "        for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = tb_mix(tb_px[j * tb_gw + i], (uint32_t)c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7876; }
    { const char * tb_v7877 = "        return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7877; }
    { const char * tb_v7878 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7878; }
    { const char * tb_v7879 = "    for (long long j = y0; j < y1; j++) for (long long i = x0; i < x1; i++) tb_px[j * tb_gw + i] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7879; }
    { const char * tb_v7880 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7880; }
    { const char * tb_v7881 = "TB_API void tb_draw_rect(long long x, long long y, long long w, long long h, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7881; }
    { const char * tb_v7882 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7882; }
    { const char * tb_v7883 = "    if (tb_gpu_on) tb_gpu_rect(x, y, w, h, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7883; }
