    { const char * tb_v7885 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7885; }
    { const char * tb_v7886 = "TB_API void tb_draw_circle(long long cx, long long cy, long long r, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7886; }
    { const char * tb_v7887 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7887; }
    { const char * tb_v7888 = "    if (tb_gpu_on) tb_gpu_circle(cx, cy, r, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7888; }
    { const char * tb_v7889 = "    if (TB_CPU_DRAW) {   // только строки и столбцы внутри окна: огромный круг не перебирает r*r точек\n"; *(const char * *)tb_grow(v_lines) = tb_v7889; }
    { const char * tb_v7890 = "        long long ja = -r > -cy ? -r : -cy, jb = r < tb_gh - 1 - cy ? r : tb_gh - 1 - cy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7890; }
    { const char * tb_v7891 = "        long long ia = -r > -cx ? -r : -cx, ib = r < tb_gw - 1 - cx ? r : tb_gw - 1 - cx;\n"; *(const char * *)tb_grow(v_lines) = tb_v7891; }
    { const char * tb_v7892 = "        for (long long j = ja; j <= jb; j++) for (long long i = ia; i <= ib; i++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7892; }
    { const char * tb_v7893 = "            if (i * i + j * j <= r * r + r) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7893; }
    { const char * tb_v7894 = "                if ((c >> 24) & 255) { uint32_t *p = &tb_px[(cy + j) * tb_gw + cx + i]; *p = tb_mix(*p, (uint32_t)c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7894; }
    { const char * tb_v7895 = "                else tb_put(cx + i, cy + j, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7895; }
    { const char * tb_v7896 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v7896; }
