    { const char * tb_v7898 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7898; }
    { const char * tb_v7899 = "TB_API void tb_draw_line(long long x0, long long y0, long long x1, long long y1, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7899; }
    { const char * tb_v7900 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7900; }
    { const char * tb_v7901 = "    long long dx = x1 > x0 ? x1 - x0 : x0 - x1, dy = y1 > y0 ? y0 - y1 : y1 - y0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7901; }
    { const char * tb_v7902 = "    long long sx = x0 < x1 ? 1 : -1, sy = y0 < y1 ? 1 : -1, e = dx + dy;\n"; *(const char * *)tb_grow(v_lines) = tb_v7902; }
    { const char * tb_v7903 = "    int gpu = tb_gpu_on, cpu = TB_CPU_DRAW;\n"; *(const char * *)tb_grow(v_lines) = tb_v7903; }
    { const char * tb_v7904 = "    while (1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7904; }
    { const char * tb_v7905 = "        if (gpu) tb_gpu_rect(x0, y0, 1, 1, c);   // соседние точки склеятся в полоски\n"; *(const char * *)tb_grow(v_lines) = tb_v7905; }
    { const char * tb_v7906 = "        if (cpu) tb_put(x0, y0, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v7906; }
    { const char * tb_v7907 = "        if (x0 == x1 && y0 == y1) break;\n"; *(const char * *)tb_grow(v_lines) = tb_v7907; }
    { const char * tb_v7908 = "        long long e2 = 2 * e;\n"; *(const char * *)tb_grow(v_lines) = tb_v7908; }
    { const char * tb_v7909 = "        if (e2 >= dy) { e += dy; x0 += sx; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7909; }
    { const char * tb_v7910 = "        if (e2 <= dx) { e += dx; y0 += sy; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7910; }
    { const char * tb_v7911 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7911; }
    { const char * tb_v7912 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7912; }
    { const char * tb_v7913 = "// Треугольник. Правило точек одно для процессора и видеокарты (кадры совпадают точка в точку):\n"; *(const char * *)tb_grow(v_lines) = tb_v7913; }
    { const char * tb_v7914 = "// точка (x, y) берётся по своему центру (x + 0.5, y + 0.5); углы обходятся так, что площадь > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7914; }
    { const char * tb_v7915 = "// для каждой стороны a→b: e = (bx-ax)*(2y+1-2ay) - (by-ay)*(2x+1-2ax); точка внутри, если e > 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7915; }
    { const char * tb_v7916 = "// для всех трёх, а если e == 0 — только на сторонах с by > ay или (by == ay и bx < ax).\n"; *(const char * *)tb_grow(v_lines) = tb_v7916; }
    { const char * tb_v7917 = "// Так у двух соседних треугольников общая сторона рисуется ровно один раз.\n"; *(const char * *)tb_grow(v_lines) = tb_v7917; }
    { const char * tb_v7918 = "// Углы дальше ±8192 точек: треугольник сначала обрезается рамкой вокруг окна (tb_poly_draw) —\n"; *(const char * *)tb_grow(v_lines) = tb_v7918; }
    { const char * tb_v7919 = "// тогда в шейдере (32-битные числа) ничего не переполняется.\n"; *(const char * *)tb_grow(v_lines) = tb_v7919; }
    { const char * tb_v7920 = "TB_INL long long tb_tri_clamp(long long v) { return v < -8192 ? -8192 : v > 8192 ? 8192 : v; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7920; }
    { const char * tb_v7921 = "// t = x1 y1 x2 y2 x3 y3; 0 — рисовать нечего (площадь 0 или целиком вне окна)\n"; *(const char * *)tb_grow(v_lines) = tb_v7921; }
    { const char * tb_v7922 = "TB_INL int tb_tri_prep(long long *t) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7922; }
    { const char * tb_v7923 = "    for (int i = 0; i < 6; i++) t[i] = tb_tri_clamp(t[i]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7923; }
    { const char * tb_v7924 = "    long long a2 = (t[2] - t[0]) * (t[5] - t[1]) - (t[3] - t[1]) * (t[4] - t[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v7924; }
    { const char * tb_v7925 = "    if (a2 == 0) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7925; }
    { const char * tb_v7926 = "    if (a2 < 0) { long long x = t[2], y = t[3]; t[2] = t[4]; t[3] = t[5]; t[4] = x; t[5] = y; }\n"; *(const char * *)tb_grow(v_lines) = tb_v7926; }
    { const char * tb_v7927 = "    long long x0 = t[0], x1 = t[0], y0 = t[1], y1 = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7927; }
    { const char * tb_v7928 = "    for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7928; }
    { const char * tb_v7929 = "        if (t[i] < x0) x0 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7929; }
    { const char * tb_v7930 = "        if (t[i] > x1) x1 = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7930; }
    { const char * tb_v7931 = "        if (t[i + 1] < y0) y0 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7931; }
    { const char * tb_v7932 = "        if (t[i + 1] > y1) y1 = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7932; }
    { const char * tb_v7933 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7933; }
    { const char * tb_v7934 = "    return !(x1 < 0 || y1 < 0 || x0 > tb_gw || y0 > tb_gh);\n"; *(const char * *)tb_grow(v_lines) = tb_v7934; }
    { const char * tb_v7935 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7935; }
    { const char * tb_v7936 = "TB_INL int tb_tri_edge(long long ax, long long ay, long long bx, long long by, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7936; }
    { const char * tb_v7937 = "    long long ex = bx - ax, ey = by - ay, e = ex * (2 * y + 1 - 2 * ay) - ey * (2 * x + 1 - 2 * ax);\n"; *(const char * *)tb_grow(v_lines) = tb_v7937; }
    { const char * tb_v7938 = "    return e > 0 || (e == 0 && (ey > 0 || (ey == 0 && ex < 0)));\n"; *(const char * *)tb_grow(v_lines) = tb_v7938; }
    { const char * tb_v7939 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7939; }
    { const char * tb_v7940 = "// глубина точки (x, y) по плоскости треугольника — так же, как в шейдере: 32-битные числа\n"; *(const char * *)tb_grow(v_lines) = tb_v7940; }
    { const char * tb_v7941 = "// без знака (переполнение по кругу), потом сдвиг; 0 — у самой камеры, 16777215 — далеко\n"; *(const char * *)tb_grow(v_lines) = tb_v7941; }
    { const char * tb_v7942 = "TB_INL uint32_t tb_tri3_depth(const uint32_t *pl, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7942; }
    { const char * tb_v7943 = "    uint32_t k = pl[2] + pl[0] * (uint32_t)(2 * x + 1) + pl[1] * (uint32_t)(2 * y + 1);\n"; *(const char * *)tb_grow(v_lines) = tb_v7943; }
    { const char * tb_v7944 = "    int32_t d = (int32_t)k >> 6;\n"; *(const char * *)tb_grow(v_lines) = tb_v7944; }
    { const char * tb_v7945 = "    return d < 0 ? 0u : d > 16777215 ? 16777215u : (uint32_t)d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7945; }
    { const char * tb_v7946 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v7946; }
    { const char * tb_v7947 = "// треугольник с углами в пределах ±8192 (t меняется: порядок углов); pl — плоскость глубины (3D) или 0\n"; *(const char * *)tb_grow(v_lines) = tb_v7947; }
    { const char * tb_v7948 = "// gpu, cpu — где рисовать (сетку на видеокарте может считать сама видеокарта: тогда здесь только процессор)\n"; *(const char * *)tb_grow(v_lines) = tb_v7948; }
    { const char * tb_v7949 = "static void tb_tri_draw_x(long long *t, long long c, const uint32_t *pl, int gpu, int cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7949; }
    { const char * tb_v7950 = "    if (!tb_tri_prep(t)) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v7950; }
    { const char * tb_v7951 = "    if (gpu) { if (pl) tb_gpu_tri3(t, c, pl); else tb_gpu_triangle(t, c); }\n"; *(const char * *)tb_grow(v_lines) = tb_v7951; }
    { const char * tb_v7952 = "    if (cpu) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7952; }
    { const char * tb_v7953 = "        long long xa = t[0], xb = t[0], ya = t[1], yb = t[1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7953; }
    { const char * tb_v7954 = "        for (int i = 2; i < 6; i += 2) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7954; }
    { const char * tb_v7955 = "            if (t[i] < xa) xa = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7955; }
    { const char * tb_v7956 = "            if (t[i] > xb) xb = t[i];\n"; *(const char * *)tb_grow(v_lines) = tb_v7956; }
    { const char * tb_v7957 = "            if (t[i + 1] < ya) ya = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7957; }
    { const char * tb_v7958 = "            if (t[i + 1] > yb) yb = t[i + 1];\n"; *(const char * *)tb_grow(v_lines) = tb_v7958; }
    { const char * tb_v7959 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v7959; }
    { const char * tb_v7960 = "        if (xa < 0) xa = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7960; }
    { const char * tb_v7961 = "        if (ya < 0) ya = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7961; }
    { const char * tb_v7962 = "        if (xb > tb_gw - 1) xb = tb_gw - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7962; }
    { const char * tb_v7963 = "        if (yb > tb_gh - 1) yb = tb_gh - 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v7963; }
    { const char * tb_v7964 = "        for (long long y = ya; y <= yb; y++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7964; }
    { const char * tb_v7965 = "            for (long long x = xa; x <= xb; x++)\n"; *(const char * *)tb_grow(v_lines) = tb_v7965; }
    { const char * tb_v7966 = "                if (tb_tri_edge(t[0], t[1], t[2], t[3], x, y) && tb_tri_edge(t[2], t[3], t[4], t[5], x, y) &&\n"; *(const char * *)tb_grow(v_lines) = tb_v7966; }
    { const char * tb_v7967 = "                    tb_tri_edge(t[4], t[5], t[0], t[1], x, y)) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7967; }
    { const char * tb_v7968 = "                    if (pl) {   // 3D: точка видна, если ближе того, что уже нарисовано\n"; *(const char * *)tb_grow(v_lines) = tb_v7968; }
    { const char * tb_v7969 = "                        uint32_t d = tb_tri3_depth(pl, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v7969; }
    { const char * tb_v7970 = "                        if (d >= tb_zb[y * tb_gw + x]) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v7970; }
    { const char * tb_v7971 = "                        tb_zb[y * tb_gw + x] = d;\n"; *(const char * *)tb_grow(v_lines) = tb_v7971; }
    { const char * tb_v7972 = "                    }\n"; *(const char * *)tb_grow(v_lines) = tb_v7972; }
    { const char * tb_v7973 = "                    tb_px[y * tb_gw + x] = (uint32_t)c;\n"; *(const char * *)tb_grow(v_lines) = tb_v7973; }
    { const char * tb_v7974 = "                }\n"; *(const char * *)tb_grow(v_lines) = tb_v7974; }
