    { const char * tb_v7987 = "static void tb_poly_draw(double *px, double *py, int n, long long c, const uint32_t *pl) {\n"; *(const char * *)tb_grow(v_lines) = tb_v7987; }
    { const char * tb_v7988 = "    double gx0 = -2048, gy0 = -2048, gx1 = tb_gw + 2048.0, gy1 = tb_gh + 2048.0;\n"; *(const char * *)tb_grow(v_lines) = tb_v7988; }
    { const char * tb_v7989 = "    if (gx1 > 8192) gx1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7989; }
    { const char * tb_v7990 = "    if (gy1 > 8192) gy1 = 8192;\n"; *(const char * *)tb_grow(v_lines) = tb_v7990; }
