    { const char * tb_v8031 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8031; }
    { const char * tb_v8032 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8032; }
    { const char * tb_v8033 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8033; }
    { const char * tb_v8034 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8034; }
    { const char * tb_v8035 = "            uint32_t v = src[j * im->w + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8035; }
    { const char * tb_v8036 = "            if ((v >> 24) >= 128) tb_px[(y + j) * tb_gw + x + i] = v & 0xFFFFFF;\n"; *(const char * *)tb_grow(v_lines) = tb_v8036; }
    { const char * tb_v8037 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8037; }
