    { const char * tb_v8039 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8039; }
    { const char * tb_v8040 = "// то же с настоящей прозрачностью: точка = округл(цвет * a / 255) + округл(фон * (255 - a) / 255).\n"; *(const char * *)tb_grow(v_lines) = tb_v8040; }
    { const char * tb_v8041 = "// Две части округляются порознь: так получается одинаково на любой видеокарте (шейдер считает первую часть сам)\n"; *(const char * *)tb_grow(v_lines) = tb_v8041; }
    { const char * tb_v8042 = "TB_API void tb_draw_image_a(long long id, long long x, long long y) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8042; }
    { const char * tb_v8043 = "    if (!tb_px || id < 0 || id >= tb_nimg) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8043; }
    { const char * tb_v8044 = "    if (tb_gpu_on) tb_gpu_image_a(id, x, y);\n"; *(const char * *)tb_grow(v_lines) = tb_v8044; }
    { const char * tb_v8045 = "    if (TB_CPU_DRAW) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8045; }
    { const char * tb_v8046 = "        tb_image *im = &tb_imgs[id];\n"; *(const char * *)tb_grow(v_lines) = tb_v8046; }
    { const char * tb_v8047 = "        const uint32_t *src = tb_imgpx + im->off;\n"; *(const char * *)tb_grow(v_lines) = tb_v8047; }
    { const char * tb_v8048 = "        long long ja = y < 0 ? -y : 0, jb = y + im->h > tb_gh ? tb_gh - y : im->h;\n"; *(const char * *)tb_grow(v_lines) = tb_v8048; }
    { const char * tb_v8049 = "        long long ia = x < 0 ? -x : 0, ib = x + im->w > tb_gw ? tb_gw - x : im->w;\n"; *(const char * *)tb_grow(v_lines) = tb_v8049; }
    { const char * tb_v8050 = "        for (long long j = ja; j < jb; j++) for (long long i = ia; i < ib; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8050; }
    { const char * tb_v8051 = "            uint32_t v = src[j * im->w + i], a = v >> 24;\n"; *(const char * *)tb_grow(v_lines) = tb_v8051; }
    { const char * tb_v8052 = "            if (a == 0) continue;\n"; *(const char * *)tb_grow(v_lines) = tb_v8052; }
    { const char * tb_v8053 = "            uint32_t *d = &tb_px[(y + j) * tb_gw + x + i];\n"; *(const char * *)tb_grow(v_lines) = tb_v8053; }
    { const char * tb_v8054 = "            if (a == 255) { *d = v & 0xFFFFFF; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8054; }
    { const char * tb_v8055 = "            uint32_t o = *d, r = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8055; }
    { const char * tb_v8056 = "            for (int sh = 0; sh <= 16; sh += 8) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8056; }
    { const char * tb_v8057 = "                uint32_t sc = (v >> sh) & 255, dc = (o >> sh) & 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8057; }
    { const char * tb_v8058 = "                uint32_t q = tb_blend_cal ? tb_blend_lut[(sc << 16) | (dc << 8) | a] : (sc * a + 127) / 255 + (dc * (255 - a) + 127) / 255;\n"; *(const char * *)tb_grow(v_lines) = tb_v8058; }
    { const char * tb_v8059 = "                r |= (q > 255 ? 255 : q) << sh;\n"; *(const char * *)tb_grow(v_lines) = tb_v8059; }
    { const char * tb_v8060 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8060; }
    { const char * tb_v8061 = "            *d = r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8061; }
