    { const char * tb_v8063 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8063; }
    { const char * tb_v8064 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8064; }
    { const char * tb_v8065 = "// текст: буква 8×16, size — во сколько раз крупнее\n"; *(const char * *)tb_grow(v_lines) = tb_v8065; }
    { const char * tb_v8066 = "TB_API void tb_draw_text(long long x, long long y, const char *s, long long size, long long c) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8066; }
    { const char * tb_v8067 = "    if (!tb_px) return;\n"; *(const char * *)tb_grow(v_lines) = tb_v8067; }
    { const char * tb_v8068 = "    if (size < 1) size = 1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8068; }
    { const char * tb_v8069 = "    const unsigned char *p = (const unsigned char *)s;\n"; *(const char * *)tb_grow(v_lines) = tb_v8069; }
    { const char * tb_v8070 = "    long long cx = x;\n"; *(const char * *)tb_grow(v_lines) = tb_v8070; }
    { const char * tb_v8071 = "    while (*p) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8071; }
    { const char * tb_v8072 = "        unsigned int u = *p++;\n"; *(const char * *)tb_grow(v_lines) = tb_v8072; }
    { const char * tb_v8073 = "        if (u >= 0x80) {   // UTF-8: собрать букву из 2–4 байт\n"; *(const char * *)tb_grow(v_lines) = tb_v8073; }
    { const char * tb_v8074 = "            int more = u >= 0xF0 ? 3 : u >= 0xE0 ? 2 : u >= 0xC0 ? 1 : 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8074; }
    { const char * tb_v8075 = "            u &= 0x3F >> more;\n"; *(const char * *)tb_grow(v_lines) = tb_v8075; }
    { const char * tb_v8076 = "            while (more-- > 0 && (*p & 0xC0) == 0x80) u = (u << 6) | (*p++ & 0x3F);\n"; *(const char * *)tb_grow(v_lines) = tb_v8076; }
    { const char * tb_v8077 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8077; }
    { const char * tb_v8078 = "        if (u == 0x2013 || u == 0x2014) u = '-';\n"; *(const char * *)tb_grow(v_lines) = tb_v8078; }
    { const char * tb_v8079 = "        if (u == 0xD7) u = 'x';   // × как x (размер окна 640×400)\n"; *(const char * *)tb_grow(v_lines) = tb_v8079; }
    { const char * tb_v8080 = "        if (u == 0xAB || u == 0xBB || u == 0x201C || u == 0x201D) u = '\"';\n"; *(const char * *)tb_grow(v_lines) = tb_v8080; }
    { const char * tb_v8081 = "        if (u == '\\n') { cx = x; y += 16 * size; continue; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8081; }
    { const char * tb_v8082 = "        int g = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8082; }
    { const char * tb_v8083 = "        if (u >= 32 && u <= 126) g = (int)u - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v8083; }
    { const char * tb_v8084 = "        else if (u >= 0x410 && u <= 0x44F) g = 95 + (int)(u - 0x410);\n"; *(const char * *)tb_grow(v_lines) = tb_v8084; }
    { const char * tb_v8085 = "        else if (u == 0x401) g = 159;\n"; *(const char * *)tb_grow(v_lines) = tb_v8085; }
    { const char * tb_v8086 = "        else if (u == 0x451) g = 160;\n"; *(const char * *)tb_grow(v_lines) = tb_v8086; }
    { const char * tb_v8087 = "        if (g < 0) g = '?' - 32;\n"; *(const char * *)tb_grow(v_lines) = tb_v8087; }
    { const char * tb_v8088 = "        if (tb_gpu_on && g != 0) tb_gpu_glyph(cx, y, g, size, c);   // 0 — пробел, рисовать нечего\n"; *(const char * *)tb_grow(v_lines) = tb_v8088; }
    { const char * tb_v8089 = "        if (TB_CPU_DRAW)\n"; *(const char * *)tb_grow(v_lines) = tb_v8089; }
    { const char * tb_v8090 = "            for (int row = 0; row < 16; row++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8090; }
    { const char * tb_v8091 = "                unsigned char bits = tb_font[g][row];\n"; *(const char * *)tb_grow(v_lines) = tb_v8091; }
    { const char * tb_v8092 = "                for (int col = 0; col < 8; col++)\n"; *(const char * *)tb_grow(v_lines) = tb_v8092; }
    { const char * tb_v8093 = "                    if (bits & (0x80 >> col)) tb_cpu_rect(cx + col * size, y + row * size, size, size, c);\n"; *(const char * *)tb_grow(v_lines) = tb_v8093; }
    { const char * tb_v8094 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8094; }
    { const char * tb_v8095 = "        cx += 8 * size;\n"; *(const char * *)tb_grow(v_lines) = tb_v8095; }
    { const char * tb_v8096 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8096; }
    { const char * tb_v8097 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8097; }
    { const char * tb_v8098 = "// ---------- 3D: сетки и камера ----------\n"; *(const char * *)tb_grow(v_lines) = tb_v8098; }
    { const char * tb_v8099 = "// Сетка — список треугольников в мире (x вправо, y вверх, z вперёд). draw_mesh поворачивает её\n"; *(const char * *)tb_grow(v_lines) = tb_v8099; }
    { const char * tb_v8100 = "// вокруг вертикали, ставит в точку, смотрит камерой (угол обзора 60°), обрезает всё ближе 0.05\n"; *(const char * *)tb_grow(v_lines) = tb_v8100; }
    { const char * tb_v8101 = "// и рисует. Ближнее закрывает дальнее: у каждой точки есть глубина (tb_zb на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v8101; }
    { const char * tb_v8102 = "// буфер глубины на видеокарте). Углы, обрезка и плоскость глубины считаются на процессоре,\n"; *(const char * *)tb_grow(v_lines) = tb_v8102; }
    { const char * tb_v8103 = "// а глубину каждой точки видеокарта и процессор считают одной и той же целой формулой:\n"; *(const char * *)tb_grow(v_lines) = tb_v8103; }
    { const char * tb_v8104 = "// кадры совпадают точка в точку.\n"; *(const char * *)tb_grow(v_lines) = tb_v8104; }
    { const char * tb_v8105 = "// сетка: свои углы без повторов (у куба 8, а не 36) и треугольники как три номера угла.\n"; *(const char * *)tb_grow(v_lines) = tb_v8105; }
    { const char * tb_v8106 = "// Каждый угол поворачивается и проецируется один раз на draw_mesh, а не в каждом своём треугольнике\n"; *(const char * *)tb_grow(v_lines) = tb_v8106; }
    { const char * tb_v8107 = "// vi — те же углы в целых (× 4096, по 4 числа: x, y, z, 0) для 3D на видеокарте; bb — коробка вокруг углов;\n"; *(const char * *)tb_grow(v_lines) = tb_v8107; }
