    { const char * tb_v8305 = "// угол сетки p (× 4096) по записи r: место на экране (целые точки) и глубина D = 2^24 - 2^24 * zn / z, zn = 205 / 4096\n"; *(const char * *)tb_grow(v_lines) = tb_v8305; }
    { const char * tb_v8306 = "TB_INL void tb_m3_corner(const int32_t *r, const int32_t *p, long long f, long long *o) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8306; }
    { const char * tb_v8307 = "    long long c[3];\n"; *(const char * *)tb_grow(v_lines) = tb_v8307; }
