    { const char * tb_v8334 = "static int tb_mesh_cull(tb_mesh *m) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8334; }
    { const char * tb_v8335 = "    if (m->cullok) return m->cull;\n"; *(const char * *)tb_grow(v_lines) = tb_v8335; }
    { const char * tb_v8336 = "    m->cullok = 1; m->cull = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8336; }
