    { const char * tb_v8338 = "    uint64_t *e = (uint64_t *)malloc(sizeof(uint64_t) * (size_t)(ne ? ne : 1));\n"; *(const char * *)tb_grow(v_lines) = tb_v8338; }
    { const char * tb_v8339 = "    double vol = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8339; }
