    { const char * tb_v8341 = "        const uint32_t *ti = m->t + 3 * t;\n"; *(const char * *)tb_grow(v_lines) = tb_v8341; }
    { const char * tb_v8342 = "        for (int k = 0; k < 3; k++) e[3 * t + k] = ((uint64_t)ti[k] << 32) | ti[(k + 1) % 3];\n"; *(const char * *)tb_grow(v_lines) = tb_v8342; }
    { const char * tb_v8343 = "        const double *p = m->v + 3 * ti[0], *q = m->v + 3 * ti[1], *r = m->v + 3 * ti[2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8343; }
    { const char * tb_v8344 = "        vol += p[0] * (q[1] * r[2] - q[2] * r[1]) + p[1] * (q[2] * r[0] - q[0] * r[2]) + p[2] * (q[0] * r[1] - q[1] * r[0]);\n"; *(const char * *)tb_grow(v_lines) = tb_v8344; }
    { const char * tb_v8345 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8345; }
    { const char * tb_v8346 = "    qsort(e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64);\n"; *(const char * *)tb_grow(v_lines) = tb_v8346; }
    { const char * tb_v8347 = "    int closed = ne > 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8347; }
    { const char * tb_v8348 = "    for (long long i = 0; i < ne && closed; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8348; }
    { const char * tb_v8349 = "        if (i + 1 < ne && e[i] == e[i + 1]) closed = 0;   // одна сторона дважды в одну сторону\n"; *(const char * *)tb_grow(v_lines) = tb_v8349; }
    { const char * tb_v8350 = "        uint64_t back = (e[i] << 32) | (e[i] >> 32);\n"; *(const char * *)tb_grow(v_lines) = tb_v8350; }
    { const char * tb_v8351 = "        if ((uint32_t)e[i] == (uint32_t)(e[i] >> 32) || !bsearch(&back, e, (size_t)ne, sizeof(uint64_t), tb_cmp_u64)) closed = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8351; }
    { const char * tb_v8352 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8352; }
    { const char * tb_v8353 = "    free(e);\n"; *(const char * *)tb_grow(v_lines) = tb_v8353; }
    { const char * tb_v8354 = "    if (closed && fabs(vol) > 1e-12) m->cull = -1;\n"; *(const char * *)tb_grow(v_lines) = tb_v8354; }
