    { const char * tb_v8716 = "                v->lpr += ar * (r - v->lpr);\n"; *(const char * *)tb_grow(v_lines) = tb_v8716; }
    { const char * tb_v8717 = "                l = v->lpl;\n"; *(const char * *)tb_grow(v_lines) = tb_v8717; }
    { const char * tb_v8718 = "                r = v->lpr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8718; }
    { const char * tb_v8719 = "            } else if (s->ch > 1) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8719; }
