    { const char * tb_v8722 = "            } else {\n"; *(const char * *)tb_grow(v_lines) = tb_v8722; }
    { const char * tb_v8723 = "                l = r = tb_sread(s, v->pos, 0, v->loop);\n"; *(const char * *)tb_grow(v_lines) = tb_v8723; }
