    { const char * tb_v8731 = "                else { done = 1; break; }\n"; *(const char * *)tb_grow(v_lines) = tb_v8731; }
    { const char * tb_v8732 = "            }\n"; *(const char * *)tb_grow(v_lines) = tb_v8732; }
    { const char * tb_v8733 = "        }\n"; *(const char * *)tb_grow(v_lines) = tb_v8733; }
    { const char * tb_v8734 = "        v->gl = tl; v->gr = tr; v->dl = tdl; v->dr = tdr;\n"; *(const char * *)tb_grow(v_lines) = tb_v8734; }
    { const char * tb_v8735 = "        if (done || v->stop) tb_voice_end(v);\n"; *(const char * *)tb_grow(v_lines) = tb_v8735; }
    { const char * tb_v8736 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8736; }
    { const char * tb_v8737 = "    float mt = (float)tb_master;\n"; *(const char * *)tb_grow(v_lines) = tb_v8737; }
    { const char * tb_v8738 = "    pthread_mutex_unlock(&tb_slock);\n"; *(const char * *)tb_grow(v_lines) = tb_v8738; }
    { const char * tb_v8739 = "    // общая громкость (плавно) и ограничитель: громко — сразу тише, потом медленно назад\n"; *(const char * *)tb_grow(v_lines) = tb_v8739; }
    { const char * tb_v8740 = "    float dm = (mt - tb_mg) / n;\n"; *(const char * *)tb_grow(v_lines) = tb_v8740; }
    { const char * tb_v8741 = "    for (int i = 0; i < n; i++) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8741; }
