    { const char * tb_v8744 = "        float pk = fabsf(l) > fabsf(r) ? fabsf(l) : fabsf(r);\n"; *(const char * *)tb_grow(v_lines) = tb_v8744; }
    { const char * tb_v8745 = "        if (pk * tb_lim > 0.98f) tb_lim = 0.98f / pk;\n"; *(const char * *)tb_grow(v_lines) = tb_v8745; }
