    { const char * tb_v8749 = "        out[2 * i + 1] = r > 1 ? 1 : r < -1 ? -1 : r;\n"; *(const char * *)tb_grow(v_lines) = tb_v8749; }
    { const char * tb_v8750 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v8750; }
    { const char * tb_v8751 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8751; }
    { const char * tb_v8752 = "static long long tb_snd_now_us(void) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8752; }
    { const char * tb_v8753 = "    struct timespec ts;\n"; *(const char * *)tb_grow(v_lines) = tb_v8753; }
