    { const char * tb_v8756 = "}\n"; *(const char * *)tb_grow(v_lines) = tb_v8756; }
    { const char * tb_v8757 = "// без устройства: время идёт как настоящее, звук — в файл (TB_SOUND_FILE) или никуда\n"; *(const char * *)tb_grow(v_lines) = tb_v8757; }
    { const char * tb_v8758 = "static void tb_snd_paced(FILE *f) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8758; }
    { const char * tb_v8759 = "    float buf[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8759; }
    { const char * tb_v8760 = "    short pcm[TB_SBLOCK * 2];\n"; *(const char * *)tb_grow(v_lines) = tb_v8760; }
    { const char * tb_v8761 = "    unsigned long long bytes = 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v8761; }
    { const char * tb_v8762 = "    long long next = tb_snd_now_us();\n"; *(const char * *)tb_grow(v_lines) = tb_v8762; }
    { const char * tb_v8763 = "    for (;;) {\n"; *(const char * *)tb_grow(v_lines) = tb_v8763; }
