    { const char * tb_v8943 = "        tb_err = sz >= 4 && memcmp(b, \"OggS\", 4) == 0 ? \"OGG пока не умею: сохрани звук как WAV\" : \"это не WAV-файл\";\n"; *(const char * *)tb_grow(v_lines) = tb_v8943; }
