    { const char * tb_v9019 = "// голос по номеру (под замком); старый номер (голос уже другой) — 0\n"; *(const char * *)tb_grow(v_lines) = tb_v9019; }
    { const char * tb_v9020 = "static tb_voice *tb_voice_at(long long id) {\n"; *(const char * *)tb_grow(v_lines) = tb_v9020; }
