    { const char * tb_v9036 = "    if (!d) return 0;\n"; *(const char * *)tb_grow(v_lines) = tb_v9036; }
    { const char * tb_v9037 = "    long long ramp = TB_SR / 200;\n"; *(const char * *)tb_grow(v_lines) = tb_v9037; }
