    { const char * tb_v9043 = "        d[i] = (float)(0.5 * e * sin(6.283185307179586 * hz * (double)i / TB_SR));\n"; *(const char * *)tb_grow(v_lines) = tb_v9043; }
    { const char * tb_v9044 = "    }\n"; *(const char * *)tb_grow(v_lines) = tb_v9044; }
